  str_story_banner_251 = "<color=#FFB400>Pilih warna sambungan yang sesuai agar Aurorian bisa menyerang</color>!",
  str_story_banner_155 = "Navigator, selamat datang di medan Tantangan. Kamu hanya boleh menggunakan <color=#FFB400>Dayna</color> untuk menyelesaikan Tantangan ini.",
