  str_story_banner_193 = "Kamu sudah tahu bahwa kemampuan Aurorian dan panjang jalur saling berkaitan. <color=#FFB400>Jika jalurnya mencapai ukuran panjang tertentu</color>, Aurorian bisa memasuki <color=#FFB400>Aurora Time</color>.",
  str_story_banner_194 = "Aurora Time adalah rahasia kuno, bahkan kaum Aurorian sendiri pun tidak tahu pasti tentangnya. Mungkin suatu hari nanti kita akan bisa mengungkap kebenaran yang tersembunyi di balik rahasia langit...",
  str_story_banner_195 = "Oke, sekarang ayo buat Aurora Time!",
  str_story_banner_196 = "Capai Hyper Connection untuk memasuki Aurora Time. Aurorian <color=#FFB400>akan memperoleh peluang lagi untuk beraksi</color>!",
  str_story_banner_197 = "Kalau bisa memanfaatkannya dengan cerdas, kamu akan meraup keuntungan darinya...",
  str_story_banner_198 = "N-navigator, apa ini Aurora!? Dunia seakan-akan berhenti berputar! Ini saat yang tepat untuk memberantas musuh!",
  str_story_banner_199 = "Ini stage spesial. Mungkin saja stage ini bisa meningkatkan beberapa teknik tempur, ya?",
  str_story_banner_201 = "Baiklah, manfaatkan Chain Combo milik Vice untuk memberantas para Eclipsite itu!",
  str_story_banner_202 = "Abyssal Terrain memisahkan kita dari musuh. Kita harus mencari cara untuk membalas...",
  str_story_banner_203 = "Vice benar. Apa kamu lihat Tile biru di medan tempur itu? Ayo ke sana!",
  str_story_banner_207 = "Cepat pergi ke titik keluar!",
  str_story_banner_210 = "Huh, Light Trail ini tampak menarik. Mungkin sudah saatnya kamu harus menguasai kunci berikutnya untuk bertempur.",
  str_story_banner_211 = "Apa kamu lihat tata letak <color=#FFB400>Tile merah itu</color>?",
  str_story_banner_212 = "Kemampuan Aurorian dipengaruhi oleh panjang jalur. Kalau <color=#FFB400>jalurnya bisa disambung hingga mencapai panjang tertentu</color>, Aurorian akan bisa memasuki <color=#FFB400>Aurora Time</color>.",
  str_story_banner_213 = "Aurora Time adalah rahasia kuno... Mungkin, sama seperti White Night—\nmisteri yang menanti untuk kita pecahkan.",
  str_story_banner_214 = "Oke, sekarang ayo buat Aurora Time!",
  str_story_banner_215 = [[
Situasinya makin sulit... Fokus, Caelestite.
Ayo tunjukkan kemampuanmu!]],
  str_story_banner_216 = [[
Hati-hatilah dengan senjata tempur spesial itu. Senjata itu akan <color=#FFB400>menyerang
target pertama di depannya dalam garis lurus</color>, dan rasanya SAKIT!]],
  str_story_banner_217 = "Para \"profesional\" kita sedang membongkarnya, jadi kamu hanya perlu <color=#FFB400>bertahan 7 putaran lagi</color> agar menang! Kamu bisa memeriksa progresmu di sini.",
  str_story_banner_218 = "Ayo! Tunjukkan kepada mereka bahwa kita tak bisa dikalahkan semudah itu!",
  str_story_banner_219 = "Navigator... Ini mendesak, kita harus melindungi Eve.",
  str_story_banner_220 = "Eve rentan terhadap serangan musuh, jadi kita harus bergerak lebih cepat daripada musuh!",
  str_story_banner_221 = "Navigator, kali ini pun kami mengandalkanmu. Aku percaya padamu!",
  str_story_banner_222 = [[
Navigator, <color=#FFB400>Collector</color> diserang Eclipsite!
Kita <color=#FFB400>harus melindungi perangkat itu</color>!]],
  str_story_banner_223 = "Karena Eclipsite sekarang sedang unggul, kita harus membasmi mereka yang berhasil lolos!",
  str_story_banner_224 = [[
Collector juga dilengkapi sejumlah fitur sederhana yang bisa membantu kita melawan para Eclipsite ini.
Tapi ingat, fiturnya <color=#FFB400>hanya bisa digunakan satu kali per putaran.</color>]],
  str_story_banner_225 = [[
Eclipsite akan terus berdatangan, tapi kita harus bertahan!
Kita harus <color=#FFB400>melindungi Collector</color> agar tidak dihancurkan!]],
  str_story_banner_226 = "Untuk mengaktifkan fitur Collector, kita butuh energi. Kamu lihat <color=#FFB400>Energy Bar</color> itu, 'kan?",
  str_story_banner_227 = "Serangan sebelumnya mengakibatkan Collector retak-retak. Ayo lakukan <color=#FFB400>Perbaikan Darurat</color>!",
  str_story_banner_228 = "Aaaargh, ini tidak ada habisnya! Jangan lupa, gunakan <color=#FFB400>Energy Shield</color> dari Collector saat situasimu terjepit! Dia bisa menahan damage <color=#FFB400>3 kali</color>!",
  str_story_banner_229 = [[
Bedebah-bedebah itu memang sinting, mereka berusaha mencegah kita lepas landas.
Selain itu, Light Trail juga tidak ideal. Kita dalam masalah.]],
  str_story_banner_230 = "Eh, eh. Dalam situasi seperti ini, sebaiknya gunakan orang yang punya kemampuan serangan berkelompok, misalnya aku!",
  str_story_banner_704 = "Dia muncul lagi! Si licik Dayna itu!?",
  str_story_banner_231 = "Ssttt, jangan berisik. Dengan susunan Lumina yang ada saat ini... Yap! Cepat! tempatkan aku di posisi <color=#FFB400>Kapten</color>!",
  str_story_banner_232 = "Cedera? Kamu harus minta <color=#FFB400>Zoya</color> untuk menangani lukamu.",
  str_story_banner_233 = "Tapi, kamu juga tak boleh mengabaikan jalur bagus di dekatnya! <color=#FFB400>Biarkan Zoya di depan</color> dan memandu kita melewati jalur kuning!",
  str_story_banner_234 = [[
Sekarang giliranku menghadapi musuh yang terpencar-pencar ini. Navigator, kamu masih ingat cara mengganti Kapten, 'kan?
Ingat, <color=#FFB400>kamu hanya bisa mengganti Kapten sebanyak 3 kali per pertempuran</color>, oke?]],
  str_story_banner_235 = "Gunakan Kapten dengan baik untuk membalikkan situasi pertempuran!",
  str_story_banner_236 = "Aduh... Kerikil-kerikil menyebalkan... Menjengkelkan sekali... remukkan saja mereka sampai berkeping-keping!",
  str_story_banner_237 = [[
Kilauan di Eclipsite ini... 
Sepertinya kita menghadapi masalah besar, PlayerName.]],
  str_story_banner_238 = "\"<color=#FFB400>Physical Attack Resistance</color>\" membuat <color=#FFB400>physical damage</color> berkurang banyak! Sepertinya hanya <color=#FFB400>Chain Combo</color> dan <color=#FFB400>Active Skill</color> yang bisa menimbulkan damage cukup besar!",
  str_story_banner_239 = "Bentuk Eclipsite itu sangat mencolok... Kalau tidak salah ingat, dia bisa mengeluarkan <color=#FFB400>petir kuat</color>!",
  str_story_banner_240 = "<color=#FFB400>Ketuk Eclipsite</color> untuk melihat lokasi persis target. Seperti biasa, pimpin kami menuju kemenangan!",
  str_story_banner_241 = [[
Sepertinya baru kali ini kita menghadapi Eclipsite jenis ini.
Beri aku waktu sebentar untuk memeriksa catatanku. Yang satu ini masalah besar...]],
  str_story_banner_242 = "Ketemu! Eclipsite tipe ini <color=#FFB400>bisa memberikan buff untuk rekan-rekan di sekitarnya.</color> Apa kita singkirkan dia dulu...?",
  str_story_banner_243 = [[
Semua tindakan pasti ada konsekuensinya, 'kan? Ingat Eclipsite yang punya Normal Attack Resistance tinggi itu?
Nah, yang ini justru sebaliknya. Dia punya <color=#FFB400>Skill Resistance</color>!]],
  str_story_banner_244 = "Damage dari <color=#FFB400>Chain Combo</color> dan <color=#FFB400>Active Skill</color> jadi <color=#FFB400>berkurang banyak</color>! Dengan kata lain, hantam satu per satu sampai dia kalah!",
  str_story_banner_245 = "Apa? Kenapa Eclipsite tipe ini ada di sini? Mundur, Navigator!",
  str_story_banner_246 = [[
Yang ini akan <color=#FFB400>menghancurkan dirinya sendiri</color> saat HP-nya turun hingga kurang dari nilai tertentu, sehingga akan menimbulkan damage besar ke area di sekitarnya!
Coba gunakan Ranged Attack!]],
  str_story_banner_247 = "Kemarilah, tentu saja ada hal baru yang muncul...",
  str_story_banner_248 = "\"Eclipsite tipe ini telah diperkuat dengan elemen tertentu, dan yang bisa menimbulkan damage kepada mereka secara efektif hanyalah Aurorian yang punya <color=#FFB400>elemen yang berlawanan</color>...\"",
  str_story_banner_713 = [[
Yang ini bisa dilawan dengan elemen Water, jadi serahkan saja padaku.
Kalau kamu membiarkan orang lain menyerang, akan sulit jadinya...]],
  str_story_banner_249 = "Berkat petunjuk darimu, kekuatan tempurku jadi meningkat banyak dalam pertempuran baru-baru ini!",
  str_story_banner_252 = "Jangan biarkan Eclipsite itu kabur! Ayo terus bertarung berpasangan!",
  str_story_banner_253 = "Spellhound punya 3 lapisan Shield. Agak sulit untuk menghancurkan Shield itu sekaligus...",
  str_story_banner_254 = [[
Sebaiknya jadikan aku Kapten sekarang!
Dengan begitu, kalau kamu menggunakan <color=#FFB400>Water</color>, aku bisa menyerang serentak bersama Vice dan Ms. Blanc!]],
  str_story_banner_255 = "PlayerName, apa kamu lihat? Damage yang diterima kedua Spellhound ini berbeda!",
  str_story_banner_256 = [[
Sama seperti kita, Eclipsite juga punya elemen.
Kalau kita menyerang Eclipsite dengan menggunakan elemen yang sesuai, damage yang ditimbulkan akan lebih besar.]],
  str_story_banner_257 = "Water menang lawan Fire, Fire menang lawan Forest, Forest menang lawan Thunder, dan Thunder menang lawan Water!",
  str_story_banner_258 = "PlayerName, pimpin kami untuk mengalahkan para Eclipsite itu!",
  str_story_banner_259 = "Kalau kamu menunjuk Vice menjadi Kapten untuk bagian Tile kuning berikutnya, aku dan dia bisa menyerang serentak!",
  str_story_banner_301 = "Aah, Lumo Soldier ini membuatku ingat masa lalu!",
  str_story_banner_302 = "<color=#FFB400>Ketuk</color> untuk melihat <color=#FFB400>informasi detailnya</color>!",
  str_story_banner_303 = "Ho! Coba lihat! Ini apa, ya? Apa Lumopolis bahkan sampai menggunakan <color=#FFB400>Trap</color> lawas ini?",
  str_story_banner_304 = "Hawa bahaya... Sepertinya aku pernah lihat cahaya kuning di Trap ini...",
  str_story_banner_305 = "Ternyata ini Paralysis Ballista! Coba kulihat... Mestinya ada <color=#FFB400>tombol trigger</color> di suatu bagiannya...",
  str_story_banner_306 = "Ketemu! Hihi, kita hanya perlu hati-hati menggunakannya... Sebentar, sepertinya ada yang aneh dengan posisi begundal-begundal Lumopolis itu... Bagaimana kalau...",
  str_story_banner_307 = "Seru sekali menggunakan perangkat milik begundal-begundal itu untuk menghantam mereka sendiri! Asalkan kita hati-hati, dan <color=#FFB400>tidak berdiri di lintasan tembakan perangkat ini</color>, tidak akan ada masalah!",
  str_story_banner_308 = "Tunggu! Ada yang janggal dari musuh di hadapan kita itu! Kali ini, apa lagi yang direncanakan Lumopolis?",
  str_story_banner_309 = "Brock, aku sudah pernah dengar tentang ini! Sepertinya benda itu bisa menghasilkan Phantom untuk <color=#FFB400>menghindari serangan</color>!",
  str_story_banner_310 = [[
Tapi, Phantom itu <color=#FFB400>tidak bisa membendung Paralyzing Trap</color>!
Ayo hantam mereka dengan Trap ini!]],
  str_story_banner_311 = "... Apa-apaan ini! Padahal tadi ada di sana! Sepertinya kita memang harus menggunakan Trap!",
  str_story_banner_312 = "Betul, Brock! Para keparat itu memang sulit dihadapi! <color=#FFB400>Gunakan lebih banyak Trap</color>!",
  str_story_banner_313 = [[
Biarkan saja Paralysis Trap menghantam bajingan-bajingan licin itu, 'kan?
Aku pasti bisa menanganinya!]],
  str_story_banner_314 = "Perangkat aneh apa lagi kali ini!?",
  str_story_banner_315 = [[
Apa ini... Anu, kurasa ini sepertinya semacam <color=#FFB400>Conveyor Belt</color>...?
Dari mana mereka mendapatkan alat aneh ini...?]],
  str_story_banner_316 = "Awas! Benda ini bergerak. Jangan sampai musuh mendapatkannya!",
  str_story_banner_317 = "Hah...? Eclipsite ini... imut juga, ya?",
  str_story_banner_318 = [[
Tidak, tidak, jangan tertipu dengan penampilannya!
Kalau dia itu Eclipsite, berarti dia musuh kita!]],
  str_story_banner_712 = "... Vice benar. Eclipsite tipe itu bisa <color=#FFB400>menyembuhkan rekan mereka</color>, jadi sebaiknya kita segera basmi mereka.",
  str_story_banner_319 = [[
Monster besar ini tampak berbahaya...
PlayerName, hati-hati!]],
  str_story_banner_320 = [[
Eclipsite berbulu lembut ini apa, ya?
Seingatku, ini tidak ada dalam Battle Manual...]],
  str_story_banner_321 = [[
Lagi-lagi kamu berusaha menipuku dengan penampilanmu, ya? Navigator, mundurlah untuk sementara!
Biar kami saja yang bertarung!]],
  str_story_banner_322 = "PlayerName, apa kamu melihat <color=#FFB400>Maelstrom</color> di tanah itu?",
  str_story_banner_323 = "Sepertinya...<color=#FFB400>kita bisa berpindah dengan cepat antara dua Maelstrom</color>! Menakjubkan!",
  str_story_banner_324 = "Apa ini Eclipsite tipe baru lagi? Aku sudah hampir sampai bagian akhir Battle Manual...",
  str_story_banner_325 = "PlayerName, injak <color=#FFB400>Rune Tile</color> ini. Kalau tidak, Tile-nya akan <color=#FFB400>memanggil Eclipsite lain!</color>",
  str_story_banner_326 = [[
Itu <color=#FFB400>Siphorb!</color>!
Monster <color=#FFB400>itu bisa menyerap Tile di sekitarnya yang berelemen sama untuk meningkatkan damage mereka</color>!]],
  str_story_banner_327 = "Ini <color=#FFB400>Underbelly Arena</color> di Umbraton! Kita hanya perlu mengalahkan monster yang memuntahkan Gold! Itu saja!",
  str_story_banner_328 = [[
Tapi, kenapa HP untuk para Eclipsite ini sangat aneh?
Sepertinya janggal...]],
  str_story_banner_329 = "Itu dia. Setiap kali HP <color=#FFB400>Dark Goldor</color> turun hingga kurang dari nilai tertentu, dia akan beralih ke status <color=#FFB400>Damage Immunity</color> untuk putaran ini. Sungguh keras kepala...",
  str_story_banner_330 = "Dark Goldor juga bisa melancarkan serangan <color=#FFB400>jarak lebar</color>. Pilih strategi yang tepat dan kalahkan musuh menjengkelkan ini!",
  str_story_banner_331 = "Bagus! Kita berhasil mengaktifkan <color=#FFB400>Putaran Bonus</color>! Kita sangat beruntung! Navigator, cepat!",
  str_story_banner_332 = "<color=#FFB400>Ada batas waktu untuk Putaran Bonus</color>, jadi kita harus menyingkirkan para Eclipsite ini secepat mungkin! Manfaatkan Active Skill para Aurorian semaksimal mungkin!",
  str_story_banner_333 = [[
Kamu lihat <color=#FFB400>Beacon</color> di medan itu? Beacon bisa <color=#FFB400>memberikan Shield yang akan mengurangi damage</color> untuk Eclipsite.
Atur strategimu dengan tepat!]],
  str_story_banner_334 = "Dalam pertempuran Forgotten Snow, setiap stage punya fitur masing-masing. Jangan lupa memeriksanya!",
  str_story_banner_335 = "Jumlah Eclipsite yang tertarik kemari banyak sekali. Harusnya tadi kita bongkar dulu Colossus-nya sebelum membawanya pergi... Hoi!",
  str_story_banner_336 = "Di sini ada banyak <color=#FFB400>kerikil</color> yang bisa menghambat gerakan. Chain Combo milikku bisa menyingkirkannya.",
  str_story_banner_729 = "Ambil keputusan, PlayerName!",
  str_story_banner_337 = "Wah! Kadang ada barang yang tercampur dalam bebatuan ini. Coba kita lihat!",
  str_story_banner_338 = "Yah, memang cukup menyakitkan, apalagi jumlah Eclipsite di sekitar sini sangat banyak. Ayo kita manfaatkan barang-barang ini!",
  str_story_banner_339 = [[
Tempat ini sepertinya puing-puing <color=#FFB400>gudang kuno</color>. Mungkin kamu bisa mendapatkan banyak
Fragmen Teks di sini!]],
  str_story_banner_340 = "Kamu lihat <color=#FFB400>Trap</color> di tanah itu? Asalkan kita bisa berjalan melewati tiga Trap Tile, ini mestinya akan terbuka!",
  str_story_banner_341 = "Ayo beraksi!",
  str_story_banner_342 = "Sepertinya kita berada di wilayah <color=#FFB400>perampok makam</color>. Mereka menyimpan banyak barang!",
  str_story_banner_343 = "Kalau <color=#FFB400>kita gagal mengejar dan mengalahkan mereka</color>, mereka akan <color=#FFB400>kabur</color>!",
  str_story_banner_344 = "Ayo rebut jarahan yang harusnya jadi milik kita itu!",
  str_story_banner_345 = [[
Eh, eh. Bukankah itu Rookie Knight <color=#FFB400>Tanchi</color>?
Sepertinya dia tidak sengaja mengaktifkan Trap dan sekarang terjebak di dalamnya...]],
  str_story_banner_346 = "Sial! Para Eclipsite berkumpul. Tak ada waktu untuk ragu! <color=#FFB400>Ayo lindungi Rookie Knight ini</color>!",
  str_story_banner_347 = "Awas! Trap ini sangat berbahaya.",
  str_story_banner_348 = "Trap tipe ini akan aktif kalau kita menginjaknya. Gunakan dengan hati-hati.",
  str_story_banner_501 = "Navigator, sudah saatnya memberimu pengetahuan lebih menyeluruh.",
  str_story_banner_502 = [[
Selain perekrutan, ada berbagai sistem lain di Colossus yang perlu diperbaiki.
Luangkan waktu untuk mengeksplorasinya dalam petualangan mendatang!]],
  str_story_banner_503 = [[
<color=#FFB400>Eclipsite yang lebih besar</color> bermunculan!
Tapi, itu juga berarti kita punya <color=#FFB400>sudut serang lebih banyak</color>!]],
  str_story_banner_166 = [[
Pertempuran tadi hebat! Sudah kuputuskan akan memanggilmu Navigator!
Mulai sekarang, kamu akan jadi pemimpin tim kita!]],
  str_story_banner_702 = "Tolong jangan begitu saja menyerahkan jabatan Kapten...",
  str_story_banner_504 = [[
Nah, bagaimana kalau kamu kerahkan semua rekan timmu untuk bertempur?
Ayo susun skuad Aurorian-Caelestite yang kuat!]],
  str_story_banner_505 = "Sekarang, para anggota baru sudah siap!",
  str_story_banner_506 = "Navigator, quest yang ditugaskan oleh sistem sudah ada dan harus kamu tinjau!",
  str_story_banner_507 = "Benda berkelip-kelip ini apa, ya? Apa ini semacam notifikasi sistem Colossus? Coba kita ketuk dan lihat, yuk?",
  str_story_banner_508 = [[
Oh, ternyata itu semacam <color=#FFB400>Quest Reward</color>, ya?
Apa itu berarti setiap kali berhasil menyelesaikan satu stage, kita akan memperoleh keuntungan seperti ini?]],
  str_story_banner_509 = "Saat kamu ragu tentang bagaimana cara melanjutkan petualanganmu, kamu juga bisa membuka panduan terbaru melalui layar Quest!",
  str_story_banner_510 = "Setuju! Kalau memungkinkan, <color=#FFB400>naikkan level Aurorian-mu</color> agar mereka selalu prima!",
  str_story_banner_511 = "Kamu sudah cukup paham! Ayo manfaatkan kesempatan sebaik mungkin! Ikuti aku!",
  str_story_banner_512 = "Quest ini akan membuatmu berkembang lebih cepat. Kamu hanya perlu membiasakan diri dengan dunia ini SESEGERA MUNGKIN! Pertama-tama, coba kita lihat apa saja yang tersedia!",
  str_story_banner_513 = "Siapa kamu? Ada yang bisa kubantu?",
  str_story_banner_514 = "Ehem, sepertinya ada calon rekan yang ingin bergabung.",
  str_story_banner_515 = [[
Kekuatan Dayna memang luar biasa, dan dia sudah memenangkan banyak turnamen bawah tanah di Umbraton,
tapi dia juga sangat sulit dipahami...]],
  str_story_banner_516 = "Sudah, sudah. Ayo kita lanjutkan petualangan kita!",
  str_story_banner_517 = "Sudah saatnya menggunakan Lumamber untuk <color=#FFB400>merekrut Aurorian</color>, Navigator!",
  str_story_banner_518 = "Seperti yang dibilang Vice, gunakan <color=#FFB400>Lumamber</color> untuk meluncurkan suar sinyal. Semoga ada Aurorian yang merespons.",
  str_story_banner_182 = [[
Tapi, aku tidak bisa memperkirakan ke mana cahaya takdir akan membawa suaramu,
dan siapa yang akan menjawabnya...]],
  str_story_banner_519 = "Ada beberapa Aurorian yang memberikan respons! Ayo bersiap-siap untuk berkoordinasi dengan mereka...",
  str_story_banner_532 = [[
Sudah saatnya meng-upgrade kekuatan tempur semua anggota tim!
Dove, keluarkan Material Enhancement-mu...]],
  str_story_banner_703 = "Kamu mau meminta barang-barangku lagi!?",
  str_story_banner_520 = "Lihat! Ada reward yang bisa kamu klaim lagi! Pastikan kamu memperhatikan munculnya hadiah-hadiah kecil ini...",
  str_story_banner_521 = [[
Dengan hadiah berharga ini, kamu bisa merekrut 10 Aurorian!
Tim kita makin berkembang!]],
  str_story_banner_522 = [[
PlayerName, kami baru saja menerima kabar dari Utara.
Sepertinya beberapa Experience baru bermunculan!]],
  str_story_banner_523 = [[
Sepertinya ada banyak tipe Experience yang bisa memberikan sumber daya untuk Aurorian agar bisa berkembang.
Kalau sudah punya waktu, coba periksalah!]],
  str_story_banner_524 = [[
Oh, ya, dan ada jadwal baru yang sudah diaktifkan. Sebaiknya kamu segera mengonfirmasinya.
Ajak Vice untuk melihat-lihat, PlayerName.]],
  str_story_banner_260 = "Quest ini <color=#FFB400>di-refresh setiap hari</color>! Mungkin quest ini bisa membantu kita mengumpulkan sumber daya yang dibutuhkan!",
  str_story_banner_525 = "Dapatkan Reward keren seperti Lumamber dengan cara mengumpulkan Poin Aktivitas.",
  str_story_banner_705 = "Ini bisa digunakan untuk membayar biaya sehari-hari untuk Colossus di kemudian hari... Kita juga harus mulai mempelajari cara mengoperasikan Colossus...",
  str_story_banner_706 = "Sepertinya dia sudah siap menjadi wakilmu, ya?",
  str_story_banner_526 = "Navigator, awas, di depanmu!",
  str_story_banner_527 = [[
Jalannya bercabang di sini. Satu akan membawamu terus maju dalam petualanganmu, yang satunya lagi sepertinya <color=#FFB400>bercabang lagi ke stage lain</color>.
Kalau tertarik, coba periksa saja!]],
  str_story_banner_528 = "Kamu mungkin akan menghadapi sejumlah pertempuran istimewa di rute cabang ini. Kalau sudah punya waktu, coba periksa saja!",
  str_story_banner_529 = [[
Tunggu, walaupun kamu memang bisa langsung ke tujuanmu dengan mengetuk Quest Guide,
aku menemukan tempat lain yang bisa membawa kita ke sana! Ikuti aku!]],
  str_story_banner_530 = [[
Di layar Home, ketuk <color=#FFB400>Quest</color> untuk langsung pergi ke tujuan petualanganmu!
Baru tahu, ya? Aku juga baru saja tahu, kok!]],
  str_story_banner_531 = "... Dasar bocah keras kepala.",
  str_story_banner_533 = "<color=#FFB400>Aurorian Ascension</color> akan membuat kemampuan Aurorian meningkat banyak, sekaligus meningkatakan <color=#FFB400>Level Maks</color> Aurorian itu, yang merupakan sarana sangat penting untuk perkembangan.",
  str_story_banner_534 = "Kamu dapat meningkatkan Aurorian setelah mengumpulkan semua material yang dibutuhkan untuk <color=#FFB400>Ascension Aurorian</color> dan meng-upgrade-nya ke level maksimum saat ini.",
  str_story_banner_535 = "Navigator, kamu baru saja mengumpulkan material berharga—<color=#FFB400>Heartstone</color>!\nSekarang kita bisa melakukan <color=#FFB400>Aurorian Breakthrough</color>! Ikuti aku!",
  str_story_banner_536 = [[
Aurorian Breakthrough <color=#FFB400>akan meningkatkan atribut Aurorian</color> dan memperkuat <color=#FFB400>skill mereka</color>!
Cobalah!]],
  str_story_banner_537 = "Seluruh Colossus ini menyala! Apa ini berarti kita bisa melakukan perbaikan sistem sederhana?",
  str_story_banner_707 = "Apa pun itu, coba kita lakukan pemeriksaan cepat pada Colossus ini! Kondisi Soroz juga sangat penting karena dialah tempat berlindung kita!",
  str_story_banner_708 = [[
Banyak area yang dulunya tertutup sekarang bisa dibuka.
Setelah 17 tahun terbengkalai, akhirnya sekarang kita bisa menggunakan ruang-ruang ini!]],
  str_story_banner_538 = "Aku hampir lupa. <color=#FFB400>Ms. Blanc</color> baru saja direkrut. Ayo minta dia bergabung ke tim kita!",
  str_story_banner_539 = "Semua sudah siap! Ayo lanjutkan petualangan kita!",
  str_story_banner_540 = "Pintu masuk ke Secret Territory terbuka. Kita harus melihat-lihatnya sebentar.",
  str_story_banner_541 = "Pintu masuk ke Secret Territory terbuka tidak lama, jadi pastikan kamu mengeksplorasi sebanyak mungkin sementara pintunya masih terbuka!",
  str_story_banner_542 = "Di Secret Territory, kita akan menggunakan MS, bukan Prism. Ini adalah sumber daya menakjubkan yang diproduksi oleh Colossus!",
  str_story_banner_543 = "Setiap putaran dalam pertempuran Secret Territory membutuhkan 1 MS. Setelah semua MS habis terpakai, kita tidak bisa melanjutkan lagi!",
  str_story_banner_544 = "Ada banyak jalan yang bisa dipilih saat bertempur di Secret Territory, tapi semuanya mengarah ke tujuan yang sama. Jadi, hati-hatilah saat memilih jalan, karena efek tempur yang diberikannya berbeda-beda...",
  str_story_banner_545 = "Tantangan... untuk menghasilkan uang, dibutuhkan untuk... memperbaiki dan melindungi Colossus, serta untuk membeli makanan untuk kita... membayar berbagai pengeluaran...",
  str_story_banner_546 = [[
Jangan sampai Vice mendadak jadi terlalu bersemangat setiap kali mendengar kata "uang"! Istirahatlah, semoga lekas membaik!
Dia bekerja terlalu keras!]],
  str_story_banner_547 = "Sepertinya ada beragam tingkat <color=#FFB400>kesulitan</color> yang bisa dipilih, jadi pilih saja sesuai kemampuanmu.",
  str_story_banner_548 = "Affinity antara dirimu dan Aurorian bisa sedikit memengaruhi mereka, jadi kamu harus lebih memperhatikan mereka.",
  str_story_banner_549 = "Apa ada Aurorian yang terlintas di pikiranmu? Misalnya <color=#FFB400>Vice</color>, yang belum lama ini cedera demi melindungimu? Bagaimana kalau kamu menyemangatinya?",
  str_story_banner_550 = "Bagaimana kalau kamu berikan <color=#FFB400>hadiah</color> untuk Vice? Mungkin hadiah itu bisa membuatnya senang.",
  str_story_banner_551 = "<color=#FFB400>Pemberian Hadiah</color> bisa meningkatkan <color=#FFB400>Affinity</color> antara dirimu dan Aurorian, membuka lebih banyak <color=#FFB400>File</color>, dan bahkan meningkatkan beberapa <color=#FFB400>atribut</color> mereka.",
  str_story_banner_552 = "Pilih hadiah di sini, lalu kamu hanya perlu mengetuk Pemberian Hadiah di bawah ini!",
  str_story_banner_553 = "Syukurlah Charon selamat dan baik-baik saja... Siapa sangka ternyata selama ini dia menyimpan \"kejutan\" seperti itu?",
  str_story_banner_554 = "PlayerName, <color=#FFB400>Adventure Tales</color> sudah terbuka! Kau mau lihat seperti apa keseruan petualangan di luar cerita utama?",
  str_story_banner_556 = "Kalau lelah bertualang, bagaimana kalau kamu bersantai sebentar dengan mengikuti Extra Chapter ini?",
  str_story_banner_557 = "PlayerName, apa kamu masih ingat <color=#FFB400>Growth Quests</color>? Sepertinya kita berhasil menyelesaikan cukup banyak Growth Quest. Coba lihat!",
  str_story_banner_558 = "Lumayan bagus juga, ya? Ayo klaim reward-nya!",
  str_story_banner_559 = [[
Pandangan Dayna benar-benar tajam... Ayo cepat selesaikan quest ini dan
rekrut dia ke tim kita!]],
  str_story_banner_560 = "Aku baru saja mengambil benda ini dari salah satu Eclipsite. Benda ini berat dan sepertinya penting... Mungkin nanti bisa bermanfaat, ya?",
  str_story_banner_561 = "Itu <color=#FFB400>Central Plugin</color>! Itu komponen penting untuk memugar Colossus dan meng-upgrade jembatan!",
  str_story_banner_562 = "Ayo, coba lihat apa benda ini masih bisa berfungsi—ikuti petunjukku!",
  str_story_banner_563 = "Gunakan <color=#FFB400>Central Plugin</color> untuk meng-upgrade jembatan. Apa kamu tahu caranya?",
  str_story_banner_564 = "Saat ini material kita belum cukup untuk melakukan upgrade! Kita harus menyelesaikan lebih banyak<color=#FFB400>Colossus Resource Raid</color> untuk memperoleh lebih banyak material!",
  str_story_banner_565 = "PlayerName. Salah satu modul di antara data lama tak terpakai yang ada padaku baru saja diaktifkan. Ternyata ini koordinat!",
  str_story_banner_567 = "Rupanya di sana...",
  str_story_banner_568 = "Hawa di tempat ini terasa seram. Mungkin belum pernah ada Aurorian yang mengeksplorasi tempat ini...",
  str_story_banner_569 = [[
Aku tidak yakin tentang arti koordinat ini, tapi sepertinya ini membuatku ingat sesuatu.
Kamu mau melihatnya?]],
  str_story_banner_570 = "Kadar Lumina di area ini sangat lemah. Rasanya seperti ada di sisi lain kontinen ini yang dikuasai oleh Eclipsite.",
  str_story_banner_571 = "Masuk tanpa perlindungan sama saja dengan bunuh diri. Biar kulihat apakah ada item di Colossus yang bisa kita manfaatkan.",
  str_story_banner_573 = [[
Tidak disangka... ternyata aku masih menyimpan benda ini?
<color=#FFB400>Artificial Sun</color> mini ini bisa melindungi kita agar tidak tercemar kegelapan di Secret Territory!]],
  str_story_banner_574 = [[
Memang, Lumina yang diberikannya terbatas.
Di bagian <color=#FFB400>"MS"</color>, kamu bisa melihat berapa banyak energi yang tersisa.]],
  str_story_banner_575 = "Sementara kamu mengeksplorasi, <color=#FFB400>MS</color> akan berkurang secara bertahap. Begitu nilainya mencapai <color=#FFB400>0</color>, kamu harus menyelamatkan diri! Bertindaklah sesuai dengan kemampuanmu!",
  str_story_banner_576 = "Ada tempat khusus di Colossus yang digunakan untuk mengisi ulang daya, dan kalau ingin menaklukkan Secret Territory, kamu harus membuka ruang itu.",
  str_story_banner_577 = "Kamu sedang bergumam apa, sih? Namamu PlayerName, 'kan?",
  str_story_banner_578 = [[
Kalau kamu sedang memikirkan Secret Territory, kusarankan kamu masuk ke sana dengan hati-hati.
Reward-nya memang besar, tapi sudah banyak penjelajah yang tewas dan terkubur di sana.]],
  str_story_banner_722 = "Ada hal lebih penting yang harus kita lakukan, jadi keluarlah kalau ekspolasimu sudah cukup. Aku akan menunggu di luar.",
  str_story_banner_579 = "PlayerName, ada pesan baru yang masuk! Lihatlah di <color=#FFB400>Kotak Pesan</color> sekarang!",
  str_story_banner_580 = [[
PlayerName, ada cerita baru yang terbuka di <color=#FFB400>Extra Chapters</color>.
Mau coba lihat?]],
  str_story_banner_581 = "<color=#FFB400>Tarik tuasnya ke bawah</color> dan selesaikan perekrutan Aurorian!",
  str_story_banner_582 = [[
PlayerName!
Kita dapat menggunakan <color=#FFB400>Operator</color> kami dapatkan dari Colossus di sini!
Mereka akan mengurangi jumlah Prism yang diperlukan untuk menyelesaikan tahapan dan segera memberikan sumber daya!]],
  str_story_banner_583 = "Carrier sangat berharga, jadi pikirkan baik-baik kapan kamu mau menggunakannya!",
  str_story_banner_584 = "Selain itu, ada <color=#FFB400>batas penyimpanan</color> untuk Carrier, jadi sebaiknya gunakan hanya saat kamu benar-benar membutuhkannya!",
  str_story_banner_585 = [[
Eksplorasi sudah dimulai!
Sebelum bertarung melawan monster di Secret Territory, jangan lupa lihat dulu profilnya!]],
  str_story_banner_586 = [[
Ruang ini berbeda, PlayerName!
Sepertinya jumlah musuh di sini jauh lebih banyak...]],
  str_story_banner_587 = "Sesuai dugaan, ini <color=#FFB400>Elite Stage</color>! Setiap Elite Stage punya atribut stage unik, jadi kamu harus menanganinya dengan hati-hati!",
  str_story_banner_588 = "Akhirnya kita sampai di <color=#FFB400>Lounge</color>... Kita bisa <color=#FFB400>memulihkan MS</color> di sini dan istirahat sebentar! Kamu pasti lapar.",
  str_story_banner_715 = "*Mengeluarkan piring berisi organ sandworm bakar arang yang sudah disiapkan dengan cermat*",
  str_story_banner_589 = [[
Tekanan di sini jauh lebih berat daripada di Elite Stage... Tidak perlu kuberi tahu, 'kan?
Yang akan kita hadapi adalah klimaks besar...]],
  str_story_banner_590 = [[
Semua ini adalah <color=#FFB400>Relic</color> yang berhasil kita kumpulkan!
Setiap Relic punya fitur berbeda-beda, walaupun hanya bisa digunakan di Secret Territory!]],
  str_story_banner_716 = "Kalau bisa membawanya keluar akan sangat menyenangkan. Mungkin bisa dipakai untuk membayar sebagian biaya pengoperasian dan pemeliharaan Colossus... Dove akhir-akhir ini juga mendesak minta naik gaji...",
  str_story_banner_591 = "Fyuh... akhirnya berakhir juga...",
  str_story_banner_592 = [[
Tapi, yang dikatakan Mendelson tentang Schummer dan ketiga komponen itu...
Ke mana kita harus mencarinya...?]],
  str_story_banner_593 = [[
Muncul sumber sinyal baru. Apa kamu ingin menyelidiki sumbernya?
Sepertinya ini tantangan baru.]],
  str_story_banner_594 = "Ini Trial Ground yang disebut '<color=#FFB400>Spire</color>'!",
  str_story_banner_595 = [[
Kamu memang harus selalu berusaha meningkatkan kekuatanmu sebelum melangkah ke petualangan berikutnya!
Kita cari tahu lebih banyak tentang tantangan ini, yuk?]],
  str_story_banner_596 = "Spire... Reruntuhan kuno misterius. Karena kebetulan kau sudah di sini, apa kamu tertarik untuk mencobanya?",
  str_story_banner_597 = "Tentu saja! PlayerName, banyak orang sudah menjajal tantangan Spire, tapi aku belum pernah punya kesempatan untuk mengaksesnya. Kali ini, ayo kita coba!",
  str_story_banner_598 = "Baiklah, ikuti aku.",
  str_story_banner_599 = "Spire adalah tempat berkumpulnya <color=#FFB400>keempat elemen</color>, karenanya ada empat Spire, dan setiap Spire punya batas tantangannya masing-masing. Ayo kita lihat <color=#FFB400>Frost Spire</color>.",
  str_story_banner_600 = "PlayerName, kamu harus mulai dari <color=#FFB400>level pertama</color> dan memandu Aurorian untuk naik. Yang diperbolehkan ada di setiap menara <color=#FFB400>hanyalah Aurorian yang elemennya sama</color>!",
  str_story_banner_601 = "Aku tak sabar ingin melihat performamu. Semoga berhasil! Aku akan menunggu kalian semua di luar...",
  str_story_banner_602 = "Oh, aku tahu. Ini adalah tantangan yang disebut <color=#FFB400>White Night, Black Underbelly</color>, yang menawarkan banyak <color=#FFB400>uang</color> jika kamu berhasil mengalahkan musuh...",
  str_story_banner_603 = "Quest ini bisa memberikan reward ekstra, jadi pastikan kamu membuka dan menyelesaikannya saat sudah punya waktu... Hmm, <color=#FFB400>White Night, Black Underbelly</color> ini apa, ya?",
  str_story_banner_604 = "PlayerName, apa kamu lihat bahwa di Secret Territory, HP setiap Aurorian <color=#FFB400>dihitung sendiri-sendiri</color>?",
  str_story_banner_605 = [[
Anggota tim kita tiba-tiba sadar bahwa situasi jadi makin berbahaya...
Mungkin selama ini kita terlalu bergantung pada Kapten?]],
  str_story_banner_606 = "Perhatikan perubahan di medan tempur di Secret Territory! Lagi pula, semua orang baru pertama kali berada di sini...",
  str_story_banner_607 = "Berikan perintah! Kami percaya sepenuhnya kepadamu, PlayerName!",
  str_story_banner_608 = [[
PlayerName, para Aurorian ini menemukan beberapa <color=#FFB400>benda kecil</color>...
Benda-benda itu mungkin menarik untukmu, coba periksalah.]],
  str_story_banner_609 = "Ini adalah <color=#FFB400>Terminal System</color> yang memungkinkan pengguna untuk berkomunikasi satu sama lain dari jarak jauh. Aku sudah memberimu semua akses yang dibutuhkan.",
  str_story_banner_610 = "Dibandingkan dengan orang tua sepertiku, mestinya kamu mampu memahaminya dengan lebih mudah.",
  str_story_banner_611 = "Sebaiknya kita diskusikan sambil tatap muka langsung...",
  str_story_banner_650 = "Kita memperoleh item baru. Tanda-tanda ini sungguh keren!",
  str_story_banner_651 = "Menurut analisis, ini sebenarnya adalah <color=#FFB400>Secret Territory Void Cube</color> yang menunjukkan lokasi Secret Territory!",
  str_story_banner_652 = "Masukkan pola permukaan ke dalam database Colossus, mungkin itu akan membuka Kantor Eksplorasi! Ikuti aku!",
  str_story_banner_653 = "Saya telah memasukkan peta ke dalam database dan menganalisis semua informasi yang diperlukan untuk membangun Kantor Eksplorasi.",
  str_story_banner_654 = "Sekarang, mari kita mulai membangun <color=#FFB400>Kantor Eksplorasi</color>!",
  str_story_banner_1201 = "Ini apa, ya? Bentuknya aneh sekali... Jangan-jangan ini semacam Trap?",
  str_story_banner_1202 = [[
Kurasa ini akan meledak jika mengenai seseorang!
Aku penasaran apa ada cara khusus untuk mengatasinya.]],
  str_story_banner_1203 = [[
Ternyata ini... lumayan menarik...
Dibandingkan dengan menggunakan pedang saja, gaya tempur ini ternyata juga lumayan seru...]],
  str_story_banner_714 = "Tapi, kita tidak boleh lengah! Kalau aku bisa menggunakan metode ini, berarti musuh juga bisa menggunakannya!",
  str_story_banner_1204 = "PlayerName, jangan lupa, <color=#FFB400>naikkan level</color> Aurorian-mu. Dengan begitu, kamu bisa memenangkan pertempuran dengan lebih mudah!",
  str_story_banner_1205 = "Kali ini, ayo naikkan level <color=#FFB400>Ms. Blanc</color>!",
  str_story_banner_1206 = "Kamu masih ingat cara melakukannya? Cobalah sendiri!",
  str_story_banner_1207 = [[
Kita bisa <color=#FFB400>menyingkirkan</color> Hydraulic Bomb?
Apa itu berarti kita bisa menendang Eclipsite ke Hydraulic Bomb? Ayo kita coba!]],
  str_story_banner_1208 = "Spesies Eclipsite aneh ini jarang ditemui...",
  str_story_banner_1209 = "Awas! Para Eclipsite ini punya <color=#FFB400>kemampuan Knockback</color> luar biasa! Ini harus dicatat...",
  str_story_banner_2001 = "Baru pertama kali melihat bagian dalam Colossus, ya? Sekarang kelihatan masih agak berantakan karena bagian paling pentingnya, <color=#FFB400>Central Plugin</color>, hilang.",
  str_story_banner_2002 = "Kalau memungkinkan, coba cari <color=#FFB400>Central Plugin</color> sambil bertualang. Komponen ini bisa membantu memulihkan dayaku sehingga aku bisa menggunakan lebih banyak fitur.",
  str_story_banner_2003 = "Oke, pertama-tama, ayo cari tahu apa yang bisa kamu lakukan di Colossus. Fitur-fitur Colossus ditenagai oleh Lumina, jadi sebaiknya kita membiasakan diri dulu dengannya.",
  str_story_banner_2004 = "Ayo kita buka dulu <color=#FFB400>Lumina Grid</color>.",
  str_story_banner_709 = [[
Selain itu, <color=#FFB400>Firefly</color> juga dibutuhkan untuk membuka dan meng-upgrade ruang.
Sudah 17 tahun para makhluk kecil pekerja keras ini menemani kita.]],
  str_story_banner_2005 = "Terbuka! Bagus! Sekarang aku bisa menyediakan tempat dan melindungi semua orang.",
  str_story_banner_2006 = "Nah, silakan lihat <color=#FFB400>Lumina Grid</color>.",
  str_story_banner_2007 = "Ini <color=#FFB400>Lumina Grid</color>. Kamu bisa membangun <color=#FFB400>4</color> Lumina Grid, tapi kamu harus membukanya satu per satu.",
  str_story_banner_2008 = [[
Lumina Grid bukan hanya <color=#FFB400>memberikan Lumina</color>, tetapi juga <color=#FFB400>menambah kecepatan pemulihan Firefly</color>.
Lihat, Firefly-nya pelan-pelan mulai pulih.]],
  str_story_banner_2009 = "Baiklah, ayo kita lihat informasi lainnya tentang Lumina Grid.",
  str_story_banner_2010 = [[
<color=#FFB400>Aurorian bisa dikerahkan</color> untuk bekerja di setiap ruang di Colossus untuk meningkatkan efek fitur-fiturnya.
Cobalah!]],
  str_story_banner_2011 = "Setiap Aurorian punya kemampuan khusus yang berbeda-beda, dan kita harus memilih Aurorian yang sesuai untuk dikerahkan di Lumina Grid.",
  str_story_banner_2012 = "Baiklah, ayo kita lanjutkan ke <color=#FFB400>Prism Pillar</color>. Ini adalah area yang sangat penting!",
  str_story_banner_2013 = "Selamat datang kembali di <color=#FFB400>jembatan</color>! Ini adalah bagian paling penting di Colossus, jadi biar kuberitahukan apa yang kupelajari tentang Colossus sewaktu aku masih bersekolah di Illumina!",
  str_story_banner_2014 = "Jembatan bisa meningkatkan <color=#FFB400>Mood</color> maks di dalam Colossus! Lihat detailnya di sini!",
  str_story_banner_2015 = "Hmm... Coba kulihat di mana kita bisa menemukan informasi detail tentang jembatan...",
  str_story_banner_2016 = "Ah, ini dia! Selain itu, kalau sudah berhasil mengambil Central Plugin, kamu bisa menggunakannya untuk meng-upgrade jembatan dari sini!",
  str_story_banner_2017 = "PlayerName, saat ini belum ada Aurorian yang dikerahkan ke jembatan! Apa kamu lupa caranya?",
  str_story_banner_710 = "Izinkan aku mengajukan diri! Aku sudah pernah mengoperasikan platform kontrol, dan sudah belajar secara otodidak untuk mengoperasikan sistem Soroz! Izinkan aku bertugas di jembatan!",
  str_story_banner_711 = [[
Cepat sekali dia paham...
Sepertinya Vice adalah orang yang cocok untuk tugas ini sekarang.]],
  str_story_banner_2018 = "Omong-omong, aku baru saja mencatat stok dari sumber daya yang tersisa, dan sepertinya jumlahnya tidak begitu banyak.",
  str_story_banner_2019 = "Mungkin kita perlu mengeksplorasi bagian dalam Colossus. Mungkin saja ada tempat penghasil sumber daya yang sudah kembali beroperasi!",
  str_story_banner_2021 = "Sepertinya ini undangan untuk bekerja sama dengan kekuatan Aurorian lain? Aku tidak tahu banyak tentang mereka, tapi orang-orang ini jelas lihai mengumpulkan segala jenis material aneh...",
  str_story_banner_2022 = "Ini <color=#FFB400>Starlight Chamber</color>, fasilitas yang sangat penting!",
  str_story_banner_2023 = "Starlight Chamber biasanya memproduksi <color=#FFB400>Heartstone</color> berharga, tapi kadang <color=#FFB400>Star Gem</color> dan <color=#FFB400>SS Star Gem</color> juga muncul di sana. Kalau kamu punya waktu, coba cari tahu pelan-pelan!",
  str_story_banner_2024 = [[
Makin tinggi level Starlight Chamber, makin cepat pula pengumpulan Heartstone.
Dengan mengerahkan Aurorian yang sesuai, kecepatan pengumpulannya juga bisa ditingkatkan! Cobalah!]],
  str_story_banner_2025 = "Kamu ingat <color=#FFB400>Prism</color> yang kita gunakan dalam pertempuran terdahulu? Prism ini penting untuk membantu Navigator mengisi ulang energi untuk menggunakan kemampuan psikis.",
  str_story_banner_2026 = "Prism Pillar adalah fasilitas berharga yang bisa mengubah Lumina menjadi <color=#FFB400>Prism</color>.",
  str_story_banner_2027 = "Kamu bisa melihat info Prism Pillar di bilah informasi cepat di pojok kiri bawah.",
  str_story_banner_2028 = "Lihat detail selengkapnya di sini.",
  str_story_banner_2029 = [[
Ini adalah <color=#FFB400>Resource Station</color>! Aku ingat semua hal penting tentang tempat ini!
Biar kujelaskan! Ehem!]],
  str_story_banner_2030 = "Resource Station bisa menghasilkan <color=#FFB400>Carrier</color>—sekarang kamu sudah punya beberapa, 'kan?",
  str_story_banner_731 = "Ini adalah Fireflies spesial yang bertarung atas nama Anda. <color=#FFB400>Mereka akan mengurangi jumlah Prism yang diperlukan untuk menyelesaikan tahapan dan segera memberikan sumber daya</color>!",
  str_story_banner_2031 = "Ayo kita lihat cara memeriksa info Resource Station.",
  str_story_banner_2032 = [[
Pengaktifkan berbagai Resource Station ditentukan oleh level Resource Raid.
Aurorian juga bisa dikerahkan ke sini, jadi jangan sampai lupa!]],
  str_story_banner_2033 = "Baiklah, ayo kita lihat cara menggunakan Carrier!",
  str_story_banner_2034 = "PlayerName, kamu masih ingat apa yang kita bicarakan sebelumnya tentang eksplorasi Secret Territory? Sepertinya ruang tempatmu berada sekarang ini bisa digunakan untuk mengubah \"<color=#FFB400>Artificial Sun</color>\"!",
  str_story_banner_2035 = "Vice sepertinya sangat mengenalku luar dalam, bahkan lebih daripada kamu yang sudah menemaniku selama 17 tahun... Pastikan dia tetap berada di Colossus!",
  str_story_banner_2036 = "Untuk mengeksplorasi Secret Territory, kita butuh banyak <color=#FFB400>'MS'</color>, yaitu suatu zat khusus, dan <color=#FFB400>MS</color> menunjukkan seberapa banyak yang masih tersisa.",
  str_story_banner_732 = "<color=#FFB400>MS</color> bisa dipulihkan di sini seiring waktu! Lihat detail selengkapnya di sini!",
  str_story_banner_2037 = "PlayerName, koordinat Secret Territory sudah dipastikan. Nah, ayo kita lihat ke sana!",
  str_story_banner_2038 = "PlayerName! Kamu baik-baik saja!? Maaf, aku baru saja gagal membidik bagian vital Nozard... Tapi, dari tempat setinggi ini, sepertinya dia juga tidak mungkin bisa selamat, 'kan?",
  str_story_banner_717 = "Berikutnya, kita harus turun ke ketinggian yang aman. Sekarang kita memang aman dari bahaya, tapi kita tidak bisa langsung tenang. Jangan sampai ada orang lain lagi yang terpaksa mengorbankan nyawa.",
  str_story_banner_718 = "Tolong beri tahu dia, ini bukan salahnya. Seandainya saja aku bisa memanaskan diri lebih cepat, para Eclipsite itu pasti tidak akan berhasil.",
  str_story_banner_719 = "Hmm... Terbang membuatku agak lelah... Sepertinya, kerusakannya parah. Biar kuperiksa area di sekitar sini, siapa tahu ada tempat yang bisa kita gunakan untuk mengumpulkan material perbaikan...",
  str_story_banner_2020 = "PlayerName, kalau melihat postur terbang Soroz, sepertinya dia kesakitan. Sepertinya dia mengalami kerusakan cukup parah akibat pertempuran itu...",
  str_story_banner_720 = "Hmm? Tunggu, ini sumber sinyal baru... Soroz menemukan apa, ya?",
  str_story_banner_721 = "Terima kasih atas perhatianmu, Vice. Aku memang menemukan sesuatu—sepertinya ini semacam Trial yang bisa memberi kita <color=#FFB400>material konstruksi Colossus</color>. Bagaimana kalau kita coba lihat ke sana?",
  str_story_banner_2039 = "Maaf merepotkanmu, PlayerName. Kerusakan akibat pertempuran tadi ternyata parah...",
  str_story_banner_730 = "Biar kuajak kamu ke suatu tempat. Kalau bisa membangunnya ulang, berarti kamu juga bisa memperbaiki aku.",
  str_story_banner_2040 = "Dulu, tempat ini seperti tidak bernyawa. Tapi, keadaannya sekarang sudah berbeda. Kamu bisa membuat tempat ini kembali berjaya.",
  str_story_banner_2041 = "Pemeliharaan Colossus dan upgrade Aurorian butuh banyak sumber daya. Fungsi <color=#FFB400>Resource Station</color> adalah untuk mencari lebih banyak sumber daya.",
  str_story_banner_2042 = "Sekarang, bangunlah <color=#FFB400>Resource Station</color>.",
  str_story_banner_2043 = "Ruang ini akan membuat pengumpulan sumber daya kita jauh lebih efektif. Manfaatkan sebaik-baiknya.",
  str_story_banner_2044 = "PlayerName, rupanya kamu di situ! Aku baru saja menemukan Trial baru. Mungkin kita bisa mendapatkan material yang dibutuhkan untuk memperbaiki Soroz!",
  str_story_banner_2045 = "Sumber sinyalnya ada di sini, PlayerName!",
  str_story_banner_2046 = "Vice menunggumu di sini. Coba cari tahu apa yang dibutuhkannya!",
  str_story_banner_2047 = "Hmm... PlayerName, apa kamu lihat Vice?",
  str_story_banner_2048 = "Prism Pillar... Ah, kenangan-kenangan itu... Ayo kita coba memperbaikinya!",
  str_story_banner_2049 = [[
Nah, <color=#FFB400>Prism Pillar</color> sudah diaktifkan ulang.
Kemarilah dan lihat, PlayerName.]],
  str_story_banner_2050 = "Kalau punya materialnya, kita juga bisa meng-upgrade Prism Pillar untuk meningkatkan efisiensi pengubahan Prism!",
  str_story_banner_2051 = [[
Demikian halnya, dengan mengerahkan Aurorian tertentu, kecepatan pengubahan Prism Pillar juga akan meningkat.
Ayo kita coba!]],
  str_story_banner_2052 = "Kamu masih ingat cara mengerahkan Aurorian, 'kan? Coba operasikan!",
  str_story_banner_2053 = "Sistem quest sepertinya sudah diperbarui. Mau coba lihat?",
  str_story_banner_2054 = "Central Plugin hanya bisa digunakan di jembatan. Ayo cepat ke jembatan!",
  str_story_banner_2055 = "Tantang bos Desolation Codex untuk menerima peringkat, lambang avatar, dan hadiah berdasarkan kerusakan yang Anda berikan.",
  str_story_banner_2056 = "Kamu bisa melihat persyaratan damage dan reward dari semua rank di sini.",
  str_story_banner_2057 = "Di akhir setiap siklus, reward dan emblem akan diberikan sesuai dengan rank kamu. Emblem kamu akan ditampilkan di avatar pribadi sebagai simbol pencapaian.",
  str_story_banner_2058 = "Sekarang, ayo tantang boss di siklus ini!",
  str_story_banner_3001 = [[
Aurorian Ascension juga akan membuka equipment.
Biar kutunjukkan cara kerja <color=#FFB400>Aurorian Equipment</color>!]],
  str_story_banner_3002 = [[
Setiap Aurorian Equipment punya keunikan. Equipment ini bisa <color=#FFB400>meningkatkan kemampuan</color>
dan <color=#FFB400>memperkuat skill Aurorian</color>.]],
  str_story_banner_3003 = "Selain itu, Aurorian Equipment bisa memperkuat efek <color=#FFB400>elemental counter</color>, sehingga akan meningkatkan kemampuan Aurorian.",
  str_story_banner_3004 = "PlayerName! Aurorian Equipment juga bisa di-upgrade. Tentu saja, proses ini butuh sejumlah material khusus. Ayo kita periksa.",
  str_story_banner_3005 = [[
Saat ini, material kita belum cukup!
Tapi, aku yakin kita akan bisa mendapatkan semua material itu karena PlayerName ada di sini!]],
  str_story_banner_3011 = "Tunggu! Apa kamu lihat <color=#FFB400>ikon khusus</color> di atas slot tim kelima?",
  str_story_banner_3012 = "Ikon itu berarti kamu bisa menambahkan <color=#FFB400>Support Aurorian</color> di sini!",
  str_story_banner_3013 = "Melalui negosiasi, kita bisa mengajak Aurorian yang tidak ada di Colossus untuk membantu kita saat bertempur! Mereka disebut Support Aurorian.",
  str_story_banner_3014 = "Kamu harus menandatangani perjanjian dengan organisasi lain untuk memanggil Support Aurorian. Tentu saja, ada beberapa organisasi yang mau memberikan bantuan tanpa syarat!",
  str_story_banner_3015 = "Tidak semua pertempuran bisa ditempuh bersama Support Aurorian, dan Support Aurorian yang sama tidak bisa dikerahkan lebih dari satu kali dalam periode waktu yang singkat.",
  str_story_banner_3016 = "Baiklah, PlayerName! Kamu bisa memilih Support Aurorian yang menurutmu cocok. Support Aurorian itu akan mengisi posisi formasi kelima.",
  str_story_banner_3017 = "Terakhir, jangan lupa bahwa <color=#FFB400>kamu tidak bisa menyelesaikan Stage Rating Quest tertentu dengan Support Aurorian</color>!",
  str_story_banner_3018 = "Sayangnya, <color=#FFB400>kamu tidak bisa menyelesaikan Stage Rating Quest tertentu dengan Support Aurorian</color>.",
  str_story_banner_3021 = "Kita baru saja menerima pesan dari Illumina, PlayerName!",
  str_story_banner_3022 = "Coba kulihat... Pesan ini menyebutkan \"<color=#FFB400>Tempering Illumina</color>.\" Sepertinya aku pernah mendengarnya di suatu tempat sebelumnya...",
  str_story_banner_3023 = [[
Mungkinkan ini reruntuhan yang baru saja ditemukan?
Sepertinya pihak lab berhasil menggali banyak material yang mungkin bisa digunakan untuk <color=#FFB400>memperkuat equipment</color>!]],
  str_story_banner_3024 = "Ayo cepat kita cari tahu!",
  str_story_banner_3031 = "Apa <color=#FFB400>Dispatch Office</color> sudah siap? Ini berarti kita akan bisa membantu yang lainnya dengan cepat!",
  str_story_banner_3032 = "Ikuti aku! Ayo kita periksa Sand Table itu!",
  str_story_banner_3033 = "Kita bisa lihat semua <color=#FFB400>Dispatch Quest</color> di Sand Table itu! Lihat ini—",
  str_story_banner_3034 = "Sebagian besar <color=#FFB400>Dispatch Quest</color> dikeluarkan oleh berbagai Faction. Selesaikan quest bersama Aurorian dari Faction yang sama untuk memperoleh reward bonus!",
  str_story_banner_3035 = [[
Setiap quest butuh waktu untuk diselesaikan!
Setelah mantap, mulailah mengerahkan Aurorian milikmu!]],
  str_story_banner_3036 = "Bagaimana kalau kamu mencobanya sekarang, Navigator?",
  str_story_banner_3041 = "Oh! Aroma familier ini... Baunya sangat samar sekarang, tapi aku pernah menciumnya di Illumina!",
  str_story_banner_3042 = "Kalau aku tidak salah, ini pasti <color=#FFB400>Workshop</color> terbengkalai, 'kan?",
  str_story_banner_3043 = [[
Workshop adalah tempat penting untuk membuat banyak Material.
Sayang sekali kalau tidak dimanfaatkan...]],
  str_story_banner_3044 = [[
Kamu lihat <color=#FFB400>tungku</color> di tengah itu? Hati-hati, mungkin masih panas! 
Periksa dulu <color=#FFB400>konsolnya</color>!]],
  str_story_banner_3045 = "Jangan gentar dulu melihat kontrol yang tampak rumit ini. Sebenarnya ini sederhana!",
  str_story_banner_3046 = "Ingat, untuk menggunakan tungku, kita butuh <color=#FFB400>Atomic Reagents</color>. Atomic Reagents diproduksi pelan-pelan di sini.",
  str_story_banner_3047 = "Upgrade Workshop untuk membuat lebih banyak barang!\nPengingat terakhir—jangan main api!",
  str_story_banner_3051 = [[
Navigator! Aku sedang menjalankan rencana yang kunamai "Operasi Membuat Colossus Jadi Senyaman Rumah"!
Ayo <color=#FFB400>hias Colossus ini</color> bersamaku!]],
  str_story_banner_3052 = "Kalian tidak akan mendandaniku dengan rok dan dasi kupu-kupu, 'kan?",
  str_story_banner_3053 = "Aku tak sabar! Aku akan menjelaskan apa saja yang kamu butuhkan untuk mulai menghias!",
  str_story_banner_3054 = [[
Dalam petualangan, kita akan mengumpulkan segala jenis Furnishing.
Kita bisa menggunakannya untuk menghias Colossus!]],
  str_story_banner_3055 = "Untuk sementara ini, aku sudah membawa beberapa barang dari tempat lain. Kita coba yang ini dulu!",
  str_story_banner_3056 = [[
Setiap Furnishing punya karakteristik tersendiri.
Ini beberapa petunjuk sederhana. Bagaimana kalau kamu mencobanya?]],
  str_story_banner_3057 = "Kamu harus menempatkan Furniture di tempat yang tepat. Pindahkan setengah sentimeter ke sisi itu, ya?",
  str_story_banner_3058 = [[
Bagus! Furnishing sudah selesai diletakkan! Tugasmu belum selesai.
Kamu harus <color=#FFB400>menyimpan</color> perubahan yang sudah kamu lakukan.]],
  str_story_banner_3059 = "Lihat, tidak? Furniture-nya membuat <color=#FFB400>Mood</color> ruang ini meningkat!",
  str_story_banner_3060 = "Di sini kamu bisa melihat <color=#FFB400>Mood</color> Colossus.",
  str_story_banner_3061 = "Sepertinya, Mood memengaruhi semua orang! Jadi, Navigator juga bertanggung jawab untuk menghias Colossus!",
  str_story_banner_3062 = "Itu saja tentang \"Operasi Membuat Colossus Jadi Senyaman Rumah!\" Aku tak sabar ingin melihat hasil kreasimu, Navigator!",
  str_story_banner_3063 = "Kita menerima beberapa perjanjian baru! Sekarang kita bisa mengajak Aurorian yang belum bergabung dengan kita di Colossus untuk memberikan bantuan sementara dalam pertempuran!",
  str_story_banner_3071 = "PlayerName! Ayo ikut aku, ada hal menarik yang ingin kutunjukkan kepadamu!",
  str_story_banner_3082 = [[
Sepertinya, kamu bisa merekrut mereka semua 
dengan cara menyelesaikan serangkaian <color=#FFB400>Special Quest</color>!]],
  str_story_banner_3083 = "Coba kita lihat file mereka dan <color=#FFB400>pilih Aurorian mana yang akan kita rekrut lebih dulu</color>!",
  str_story_banner_3084 = [[
Nah, coba kita lihat... Apa yang kita butuhkan 
untuk menyelesaikan proses perekrutan ini?]],
  str_story_banner_3086 = "Setelah menyelesaikan semua quest dalam fase ini, fase berikutnya akan terbuka secara otomatis. Kalau bisa menyelesaikan semua quest, kamu akan memperoleh Aurorian ini.",
  str_story_banner_3087 = "Ingat, yang akan dihitung hanyalah <color=#FFB400>quest</color> untuk Aurorian <color=#FFB400>yang sedang direkrut</color>, dan tidak akan ada progres untuk Aurorian yang tidak sedang direkrut!",
  str_story_banner_3091 = "Sepertinya tantangan perekrutan ini akan selalu ada. Jangan lupa memeriksa progres quest-mu secara berkala!",
  str_story_banner_3092 = "Kekuatan misterius dan hebat menunggu kita di depan sana... Apa kita perlu mendatangi dan mengeksplorasinya?",
  str_story_banner_4000 = "Kapan ini semua akan berakhir?",
  str_story_banner_4001 = "Berapa pun waktu yang kamu miliki, kamu tidak akan pernah bisa membasmi makhluk yang disebut Eclipsite itu.",
  str_story_banner_4002 = "Aku jadi ingat kebohongan itu. Kalau sampai aku bertemu lagi dengannya, akan kubakar dia tanpa pikir panjang lagi.",
  str_story_banner_4003 = "Selalu ada orang yang yakin bahwa kita akan berubah menjadi Eclipsite, tapi pikiran orang-orang seperti itu justru lebih menakutkan daripada Eclipsite itu sendiri.",
  str_story_banner_4004 = "Pengkhianat itu memang hebat. Mestinya dulu dia mati saja.",
  str_story_banner_4005 = [[
Mungkin ini hanya perasaanku, tapi sepertinya 
si pengkhianat itu masih hidup.]],
  str_story_banner_4006 = "Sayang sekali amarahku tidak terwujud. Kalau tidak, mestinya dia sudah terbakar sebelum pedangku sempat menyabetnya.",
  str_story_banner_4007 = [[
Mungkin Claymore mengira aku akan melawan, 
jadi dia memutuskan untuk menyerangku duluan.]],
  str_story_banner_4008 = "Apa ini awal cerita baru? Semoga kali ini akhir kisahnya lebih baik.",
  str_story_banner_4009 = "Kukira sebaiknya para Hunter pergi sendirian saja, tetapi saat mereka benar-benar pergi sendirian, Frostfire dan Regal selalu menimbulkan masalah.",
  str_story_banner_4010 = "Orang-orang yang cenderung kehilangan kendali akan butuh seseorang yang punya pemikiran logis untuk mengarahkan mereka kembali ke jalan yang benar.",
  str_story_banner_4011 = "Mungkin orang lain tidak bisa memahami mengapa Claymore mengambil keputusan itu. Tapi, tidak, aku tidak mau menjelaskannya untuknya. Aku hanya menerima dan mencatatnya.",
  str_story_banner_4012 = "Dalam cerita, orang-orang yang berhasil mengatasi ujian dan masalah akan memperoleh kebahagiaan.",
  str_story_banner_4013 = "Mungkin kita gagal mengatasi ujian yang sudah digariskan.",
  str_story_banner_4014 = [[
Tepat waktu. Aku selalu punya energi 
untuk membunuh mereka, kapan pun.]],
  str_story_banner_4015 = "Kalau kamu tidak tahan melihatnya, palingkan saja wajahmu dan jangan lihat. Aku tidak mau mendengar kamu mencaci caraku membunuh Eclipsite seperti orang lain.",
  str_story_banner_4016 = "Aku dipilih, dilatih, dan menerima kekuatan ini atas kehendakku sendiri hanya untuk membasmi mereka semua, jadi kenapa para Aurorian itu malah berusaha menghentikanku?",
  str_story_banner_4017 = "Sepertinya aku jadi ingat sesuatu yang sebenarnya tidak ingin kuingat... Tidak, aku belum ingat.",
  str_story_banner_4018 = "Kenapa saat itu aku begitu penuh kebencian?",
  str_story_banner_4019 = "Mereka tidak mau nama lama mereka disebut-sebut lagi. Aku tidak tahu alasannya.",
  str_story_banner_4020 = "Lupakan saja, aku tidak mau mencari tahu sampai sejauh itu. Aku hanya ingin memburu Eclipsite seperti dulu.",
  str_story_banner_4021 = [[
Tapi, jangan sampai kamu menjadi seperti mantan 
kaptenku yang tiba-tiba saja menghunus pedang 
dan menusukku dari belakang! Itu sama sekali 
bukan tindakan yang bisa dibenarkan!]],
  str_story_banner_4022 = "Apa? Sudah lama sekali? Dan dunia ini ternyata masih sama saja seperti dulu?",
  str_story_banner_4023 = "Aku sama sekali tidak paham.",
  str_story_banner_4042 = "Navigator! Kami telah menemukan hal-hal menarik saat memperbaiki Colossus.",
  str_story_banner_4043 = "Kami butuh beberapa material untuk memperbaiki ruangan ini.",
  str_story_banner_4044 = "Ini adalah sistem perintah simulasi yang dapat membantumu berlatih, yang bisa membuat beragam situasi pertempuran sesuai dengan spesifikasimu.",
  str_story_banner_4045 = "Kamu mendapatkan Command Point setelah menyelesaikan skenario tempur. Beberapa pertempuran juga akan memberimu fragmen data.",
  str_story_banner_4046 = "Kamu bisa memilih data disk dan mulai sekarang juga!",
  str_story_banner_4047 = "Simulation Room sudah selesai... Ayo cari tahu cara menggunakannya!",
  str_story_banner_4050 = "Tamat! Maiden and the Ruins telah dimulai! Ayo kita lihat yang baru dari event ini.",
  str_story_banner_5001 = "Selamat datang di petualangan baru! Buka berbagai Story baru dan hadiah keren dalam event <color=#FFB400>Cloud Blossom Destiny</color> ini!",
  str_story_banner_5002 = "Pakai Prism di tantangan Main Story serta Resource Raid dan dapatkan <color=#FFB400>Cloud Blossom Petal</color> untuk event ini. Buka skenario dan Reward event dengan Cloud Blossom Petal.",
  str_story_banner_5003 = "Banyak Story baru yang bisa kamu temukan! Buka dengan Cloud Blossom Petal yang sudah kamu miliki!",
  str_story_banner_5004 = "Ada banyak event dalam quest. Selesaikan lebih banyak quest, dapatkan Reward lebih banyak.",
  str_story_banner_5005 = "Gunakan Cloud Blossom Petal untuk <color=#FFB400>Lucky Draw</color>! <color=#FFB400>Dapatkan hadiah</color> acak di kumpulan hadiah yang ada saat ini untuk setiap undian.",
  str_story_banner_5006 = "Ada 5 kumpulan hadiah, masing-masing berisi hadiah besar. Buka kumpulan hadiah berikutnya saat kamu mendapatkan <color=#FFB400>hadiah utama</color>.",
  str_story_banner_5007 = "Makin banyak Cloud Blossom Petal yang kamu miliki, makin banyak Reward yang bisa kamu dapatkan!",
  str_story_banner_5008 = "Jika punya pertanyaan, coba lihat peraturan event di sini!",
  str_story_banner_5010 = "Izinkan aku memperkenalkan padamu metode memancing.",
  str_story_banner_5011 = "Nah, itu saja yang perlu kau ketahui tentang memancing. Sekarang, mari kita mulai tantangannya!",
  str_story_banner_40301 = "Nah, itu mereka! Sini, mendekatlah!",
  str_story_banner_40311 = "Ini bukan salahku! Ini bukan salahku!",
  str_story_banner_40321 = "Dik!",
  str_story_banner_40322 = "...",
  str_story_banner_40323 = "Para Eclipsite itu mengincar Eve! Cepat, kita tak boleh membiarkan Eve jadi lebih menderita lagi!",
  str_story_banner_40324 = "Jangan berani-berani... menyakiti... adikku... sedikit pun!",
  str_story_banner_501401 = "Mundurlah dari adikku!",
  str_story_banner_501402 = "Adikmu kehilangan kendali, sama seperti kota ini!",
  str_story_banner_501403 = "Jika kita tidak secepatnya menemukan jalan keluar, kita akan terkubur di sini...",
  str_story_banner_501404 = "Undercity apa? Aku tidak mengerti apa yang kau katakan!",
  str_story_banner_501405 = "Jangan salahkan kami jika kami berlaku kasar kalau kau meneruskan ini...",
  str_story_banner_501406 = "Tidakkk... Gre... tel...",
  str_story_banner_501407 = "Maaf, aku tak punya pilihan... Cepat, ambil yang satunya!",
  str_story_banner_501501 = "Hei, Caelestite sahabatku. Bantu aku mengawasi sekeliling.",
  str_story_banner_501502 = "Tunggu saat yang tepat dan pilih skill untuk merangsek maju.",
  str_story_banner_501503 = "Aku akan menggesekkan ban ke jalanan untuk menyemburkan pasir pada mereka. Hal itu akan memberi mereka pelajaran sebelum kita melangkah maju.",
  str_story_banner_501504 = "Itu saja. Mudah, 'kan?",
  str_story_banner_501505 = "Hmm… mereka terus berdatangan. Menyebalkan sekali! Namun, musuh sudah berada dalam jangkauan.",
  str_story_banner_501506 = "Mau menyebarkan mainan yang sangat sakit jika terinjak?",
  str_story_banner_501507 = "Pilih skill untuk meledakkan bom atau meluncurkan misil ke arah musuh.",
  str_story_banner_501508 = "Bidik dulu sebelum melempar bom. Kalau tidak, kutendang kau keluar dari mobil!",
  str_story_banner_501509 = "Fleur bilang bahwa dia membuat alat kecil yang dapat mengubah Lumina.",
  str_story_banner_501510 = "Kau tahu, sebenarnya kami, Aurorian, tidak bisa melihat aliran Lumina. Sebagai respons, aku menertawakan raut wajahnya.",
  str_story_banner_501511 = "Jika melihat ke belakang, bisa jadi itu adalah hadiah untukmu.",
  str_story_banner_501512 = "Pilih skill Airdrop. Tentukan tempat pendaratan airdrop di sana.",
  str_story_banner_501601 = [[
Ahem! W-Selamat datang di game <color=#FFB400>Tabrak & Bakar</color>.
Ya, kamu, kamu disana... Hei! Mengapa kekerasan?]],
  str_story_banner_501602 = [[
Aku mungkin Eclipsite, tapi aku bukan musuhmu! Saya punya tugas s-khusus untuk Anda:
<color=#FFB400>Perintahkan rekan-rekan Eclipsite kita!</color>
Mengapa kamu begitu terkejut? Akui saja, Anda sudah lama ingin melakukan ini, bukan?]],
  str_story_banner_501603 = [[
Bahkan Eclipsite yang legendaris <color=#FFB400>Tuan Augean</color> ada di sini untuk membantu.
Tidak mungkin kita akan kalah kali ini!]],
  str_story_banner_501604 = "Ayolah, bantu kami <color=#FFB400>menghancurkan mobil balap Rediesel Wrench itu</color> dan memenangkannya bersama-sama!",
  str_story_banner_501605 = [[
I-Ini di sini menunjukkan ATK dan HP musuh,
dan menurut saya ini cara yang cukup mudah untuk menilai apakah Anda siap menghadapi tantangan.]],
  str_story_banner_501606 = "<color=#FFB400>Mengetuk Aurorian musuh akan menunjukkan aksi mereka selanjutnya.</color>",
  str_story_banner_501607 = "<color=#FFB400>Aurorian biasanya menargetkan unit musuh terdekat.</color>",
  str_story_banner_501608 = [[
Tapi mereka <color=#FFB400>hanya dapat bergerak di ubin elemen mereka sendiri!</color>
Jaga jarak dan lakukan yang terbaik untuk tidak membiarkan mereka menyakiti kita.]],
  str_story_banner_501609 = "Ayo beraksi!",
  str_story_banner_501610 = "I-Itu luar biasa!",
  str_story_banner_501611 = [[
Berkat kemampuan khusus Lord Augean,
<color=#FFB400>mengalahkan seorang Aurorian menyegarkan ACT kami, memungkinkan kami untuk bertindak sekali lagi.</color>]],
  str_story_banner_501612 = "Semuanya tergantung padamu sekarang!",
  str_story_banner_501613 = [[
Wow! Chasm telah bergabung dengan tim!
I-Itu akan meledakkan dirinya sendiri dan membawa musuh bersamanya!]],
  str_story_banner_501614 = "Baiklah, mari kita lihat seberapa dahsyat ledakannya!",
  str_story_banner_501615 = [[
Jurang <color=#FFB400>menimbulkan kerusakan di area berbentuk berlian di sekelilingnya.</color>
Juga <color=#FFB400>memecahkan ubin tempatnya berdiri.</color>]],
  str_story_banner_501616 = "Lihat! Longhook juga turut serta dalam pertempuran!",
  str_story_banner_501617 = [[
Tunggu sebentar. Ke-Kenapa orang-orang ini terlihat linglung?
Kait mereka tidak mencapai sejauh biasanya.]],
  str_story_banner_501618 = "<color=#FFB400>Mereka dapat mengait dan menyeret target yang berjarak hingga 3 tile di depannya.</color>",
  str_story_banner_501619 = [[
Walaupun demikian,
dalam keadaan tertentu, <color=#FFB400>menggaet sesama Eclipsites dapat membantu membalikkan keadaan.</color>]],
  str_story_banner_501620 = [[
Ini tip untuk Anda. Setelah semua Eclipsites kami menyelesaikan gerakan mereka,
<color=#FFB400>Aurorian akan menyerang unit musuh terdekat.</color>
Ketika beberapa Eclipsites sudah dekat, <color=#FFB400>mereka akan menargetkan yang memiliki HP terendah.</color>]],
  str_story_banner_501621 = [[
Bahkan ketika ada Eclipsite lain dalam jangkauan,
orang-orang Aurorian tanpa henti akan memburu yang terdekat. A-Aurorian adalah kelompok yang menakutkan...]],
  str_story_banner_501622 = [[
Tapi Anda bisa menggunakan sifat ini untuk melawan mereka! Dengan mengorbankan satu rekan setim,
Anda dapat mengizinkan Eclipsites lain untuk mendekati mereka.]],
  str_story_banner_501630 = "Tetap waspada, PlayerName. Suasana di sini terasa ganjil.",
  str_story_banner_501631 = "Kawanan monster itu memiliki wujud yang aneh.",
  str_story_banner_501632 = "Pertempuran ini menerapkan peraturan Sanity System. Saat Sanity berkurang, sejumlah efek yang sesuai akan terpicu.",
  str_story_banner_501633 = "Beberapa Aurorian tampak mampu mengubah jalannya pertempuran dengan cara yang sama. Efek skill mereka juga terpengaruh oleh Sanity Point.",
  str_story_banner_501634 = "Ingat, tetap tenang. Hadapi situasi ini dengan kepala dingin.",
  str_story_banner_501635 = "Tampaknya ada aturan tempur lanjutan.",
  str_story_banner_502701 = "PlayerName, pertempuran di sini akan berbeda dari biasanya.",
  str_story_banner_502702 = "Kaulihat <color=#FFB400>hitung mundur</color> di sana?",
  str_story_banner_502703 = "Itu adalah timer yang menunjukkan siang dan malam. Saat hitung mundur berakhir, siang dan malam akan berganti.",
  str_story_banner_502704 = "Eclipsite ini tidak bergerak, tapi…",
  str_story_banner_502705 = "Panahku tak melukainya sama sekali?!",
  str_story_banner_502706 = "Coba kulihat apakah panduan mencantumkan sesuatu terkait Eclipsite ini…",
  str_story_banner_502707 = "Aha! Menurut panduan, Eclipsite ini lemah dan berada dalam posisi bertahan saat siang hari.",
  str_story_banner_502708 = "Selama masa ini, alih-alih menyerang, dia akan fokus bertahan dan menangkis sebagian besar serangan.",
  str_story_banner_502709 = "Lalu, hanya <color=#FFB400>serangan area luas</color> yang dapat melukainya!",
  str_story_banner_502710 = "Ayo kita ubah Kapten dan kalahkan dia dengan serangan area luas!",
  str_story_banner_502711 = "PlayerName, siang dan malam telah berganti.",
  str_story_banner_502712 = "Tampaknya, Eclipsite itu juga ikut berubah. Dia mulai bergerak!",
  str_story_banner_502713 = "Hati-hati, PlayerName!",
  str_story_banner_502714 = "Akan kuserahkan sisanya padamu!",
  str_story_banner_502801 = "Apa yang dilakukan High-Level Eclipsite di sini?",
  str_story_banner_502802 = "Panduan ini tidak mencantumkan petunjuk apa pun untuk mengalahkan Eclipsite semacam ini…",
  str_story_banner_502803 = "Tampaknya kita tak bisa bertindak bebas. Kita harus mencari cara untuk melarikan diri dari sini!",
  str_story_banner_502804 = "Lihat, PlayerName, sepertinya itu jalan keluarnya!",
  str_story_banner_502805 = "Jalan keluar itu tampak bisa runtuh kapan saja. Ayo kita lari sebelum itu terjadi!",
  str_story_banner_502806 = "Jangan sampai Eclipsite itu meruntuhkan jalan keluar kita!",
  str_story_banner_502901 = "Makhluk ini… Dia berubah!",
  str_story_banner_502902 = "Tampaknya kekuatannya juga turut meningkat…",
  str_story_banner_502903 = "Hati-hati.",
  str_story_banner_503001 = "Bau tak enak ini... Dari mana asalnya?",
  str_story_banner_503002 = "Semakin aku mendekat, kekuatanku malah melemah.",
  str_story_banner_503003 = "Hindari sebisa mungkin.",
  str_story_banner_5016411 = "Lenore mengingatkanmu untuk berhati-hati, PlayerName. Eclipsite yang berdiri di kejauhan itu memberikan ancaman serius.",
  str_story_banner_5016412 = "Biar Lenore yang melenyapkan mereka sekaligus. Jika <color=#FFB400>Sanity Point</color> tidak cukup, <color=#FFB400>HP</color> dapat dikurangi sebagai gantinya.",
  str_story_banner_5016413 = "Bagus sekali, PlayerName.",
  str_story_banner_5016414 = "Eclipsite yang tersisa terpencar di mana-mana, tapi tak apa. Lenore menjadi lebih kuat jika <color=#FFB400>Sanity turun menjadi 0</color>.",
  str_story_banner_5016415 = "PlayerName, pandu Lenore untuk melancarkan Chain Combo dan melenyapkan Eclipsite yang tersisa.",
  str_story_banner_5016416 = "Hmm? Mirage? Biasanya Mirage tak akan muncul sebelum <color=#FFB400>Sanity</color> kita tersisa sedikit. Ahahah! Mungkin saja tak lama lagi kita akan tumbang.",
  str_story_banner_5016417 = "Hoam… Makhluk menyebalkan itu ternyata hanya umpan.",
  str_story_banner_5016418 = "Perasaan ini begitu menakjubkan… Kekuatan misterius ini… Hahah! Ayo singkirkan mereka semua!",
  str_story_banner_5016419 = "Demi White Night… Di mana aku? Kepalaku sakit sekali… Apa kita sudah kehabisan <color=#FFB400>Sanity</color>?",
  str_story_banner_5016420 = "Ahahah! Jangan khawatir. Aku bisa meredakan rasa sakitmu.",
  str_story_banner_5016421 = "Sudah baikan? Izinkan aku memulihkan sejumlah <color=#FFB400>Sanity</color> jika perlu.",
  str_story_banner_50303 = "Tampaknya semua material yang dibutuhkan sudah terkumpul. Chubb!",
  str_story_banner_50402 = "Ini adalah meja kerja di Hyacinth Tower. Melalui meja ini, kau bisa membangun apa pun. Chubb!",
  str_story_banner_50602 = "Tampaknya tempat ini mampu menampung empat Aurorian. Aurorian yang tinggal bersama di sini akan meningkatkan Affinity mereka! Coba undang Ms. Blanc!",
  str_story_banner_50701 = "Di sini, kau bisa melihat level Cloud Gardens.",
  str_story_banner_50801 = "Wah, ikannya banyak sekali di sungai ini! Ayo memancing!",
  str_story_banner_50804 = "Ikannya tertangkap! Cepat tarik!",
  str_story_banner_50901 = "Selamat datang di Cloud Gardens Store, Chubb! Di sini, kau bisa berdagang barang dan menyelesaikan pesanan untuk mendapatkan Cloud Gardens Rock Shard, Chubb!",
  str_story_banner_51001 = "Chubb! Chubb! Sini kuajari cara menanam pohon!",
  str_story_banner_9001 = "Chubb, Chubb!",
  str_story_banner_9002 = "Ayo kumpulkan kayu terlebih dahulu, Navigator!",
  str_story_banner_9003 = "Kayu, kayu, Chubb, Chubb!",
  str_story_banner_9004 = "Sepertinya kita butuh lebih banyak bijih.",
  str_story_banner_9005 = "Bijih, bijih, Chubb, Chubb!",
  str_story_banner_9006 = "Materialnya sudah lengkap! Sekarang serahkan padaku, Chubb!",
  str_story_banner_9007 = "Ayo coba bangun Gardens Dorm di Hyacinth Tower!",
  str_story_banner_9008 = "Ayo letakkan Dorm!",
  str_story_banner_9009 = "Sekarang, ayo undang Ms. Blanc untuk pindah ke Dormitory!",
  str_story_banner_9010 = "Sambut Ms. Blanc dan ajaklah dia mengobrol!",
  str_story_banner_9011 = "Halo, Navigator. Tampaknya ada yang ingin Vice bicarakan denganmu.",
  str_story_banner_9012 = "Kau bisa memancing di sampingku. Ayo coba sini!",
  str_story_banner_9013 = "Santai saja, Navigator, sekarang waktunya memancing.",
  str_story_banner_9014 = "Begitu semua material telah terkumpul, hampiri Chubb dan renovasi toko!",
  str_story_banner_9015 = "Kelihatannya ada yang menunggumu di toko, Navigator.",
  str_story_banner_9016 = "Serahkan pesanan ke Chubb Merchant!",
  str_story_banner_9017 = "Pesanannya sudah kauselesaikan, Navigator?",
  str_story_banner_9018 = "Pesanan selesai! Bicaralah dengan Vice sekarang!",
  str_story_banner_9019 = "Pergilah ke Hyacinth Tower dan bangun sepetak Land of Fertility!",
  str_story_banner_9020 = "Letakkan Land of Fertility di lahan kosong!",
  str_story_banner_9021 = "Ayo coba biakkan Unique Tree dan panen hasilnya!",
  str_story_banner_9022 = "Cepat, cari tempat yang sesuai untuk mereklamasi!",
  str_story_banner_503501 = "Menang telak, PlayerName!",
  str_story_banner_503502 = "Meski keadaannya darurat, kami berhasil lolos tanpa terluka!",
  str_story_banner_503503 = "PlayerName?",
  str_story_banner_503504 = "C-Carleen! PlayerName…",
  str_story_banner_503505 = "… juga masih belum menanggapiku.",
  str_story_banner_503506 = "Kalau kau bisa merasakan kami, PlayerName, jawab sekarang juga!",
  str_story_banner_503507 = "PlayerName...!",
  str_story_banner_503601 = "Kalau aku tidak salah ingat, ini adalah jalan menuju Central Core.",
  str_story_banner_503602 = "Eclipsite yang tak terhitung jumlahnya berhasil menerobos masuk ke Obelisk of Return.",
  str_story_banner_503603 = "Mempertimbangkan situasi kita saat ini, kita akan kesulitan mengalahkan mereka semua.",
  str_story_banner_503604 = "Tapi, kalau hanya melarikan diri, seharusnya tidak begitu sulit.",
  str_story_banner_504001 = "Stage Mode Pandora's Box lebih sulit dibanding Mode Normal. Bersiap-siaplah!",
  str_story_banner_504002 = "Tak hanya itu, Mode Pandora's Box juga memiliki syarat penyelesaian khusus yang memerlukan kerja sama beberapa tim sekaligus.",
  str_story_banner_5017311 = "Lebih mirip seperti stage yang mengharuskan kita bertahan hidup. Gelombang monster ini seakan tak ada habisnya...",
  str_story_banner_5017312 = "Itu seperti suara Barton! Gronru, kau juga dengar itu tidak?",
  str_story_banner_5017313 = "Sepertinya iya. Apa dia baik-baik saja?",
  str_story_banner_5017314 = "Kalau itu memang dia, kita tak perlu khawatir.",
  str_story_banner_5017315 = "Itulah yang kubicarakan denganmu tadi. Apa kau menemukan sesuatu?",
  str_story_banner_5017316 = "Yah, berdasarkan pengalamanku menyelesaikan stage...",
  str_story_banner_5017317 = "Ini bukanlah permainan!",
  str_story_banner_5017318 = "Semuanya akan baik-baik saja. Jika kita memperhatikan pola Eclipsite itu, jumlah mereka tersisa tak banyak lagi.",
  str_story_banner_5017319 = "Kalau memang begitu, ayo kita sapu bersih mereka semua.",
  str_story_banner_5017320 = "Aku akan memberikan koordinat mereka dan membantumu.",
  str_story_banner_5017321 = "Sekaranglah waktunya beraksi, Star-Piercing Spear!",
  str_story_banner_5017322 = "Ada banyak sekali Eclipsite di sini! Bagaimana kondisi Grand Marshal, ya? Apakah dia baik-baik saja? Sepertinya kita tak perlu khawatir.",
  str_story_banner_5017323 = "Oh, kalian mengepungku. Aku suka situasi seperti ini. Waktunya mencoba mainan baruku!",
  str_story_banner_5017324 = "Rasanya menakjubkan! Asalkan kita terus bertarung, kekuatan kita akan semakin meningkat...",
  str_story_banner_5017325 = "Ayo, ayo!",
  str_story_banner_5018311 = "Ada banyak sekali Eclipsite yang menghadang! Secret Trove milikku akan menumpas mereka.",
  str_story_banner_5018312 = "Payungnya terlempar lebih jauh dari dugaanku. Biar kuambil lagi payungku dan membasmi Eclipsite yang tersisa.",
  str_story_banner_5018321 = "Anu... Posisi musuh terlalu jauh dari tempatku berada... Manae, kuserahkan padamu, ya!",
  str_story_banner_5019301 = "Ada lebih banyak musuh yang masuk, ayo lakukan ini!",
  str_story_banner_5019302 = "Sekarang saatnya! Menggunakan <color=#FFB400>Keahlian khusus</color>!",
  str_story_banner_5019303 = "Ada banyak musuh Hutan. Ganti kapten sekarang dan beri mereka pelajaran!",
  str_story_banner_5020301 = "Sepertinya tidak ada rute bagi kita untuk pindah ke monster dan menyerang.",
  str_story_banner_5020302 = "Itu tidak akan menghentikan saya! Rudal Panah Surya dari mecha dinamis ini dapat membuka jalan. Cobalah sekarang!",
  str_story_banner_5020303 = "Hambatan telah dihapus! Selesaikan mereka dalam sekali jalan!",
  str_story_banner_5020311 = "Apa salah perhitungan! Saya sebenarnya terluka oleh taktik kerumunan Eclipsites.",
  str_story_banner_5020312 = "Anda tidak bisa terjebak dalam perang gesekan dengan Eclipsites ini. Anda harus menyembuhkan luka Anda dan pergi sesegera mungkin.",
  str_story_banner_5020313 = "Anda masih dapat menggunakan Combust beberapa kali lagi. Dapatkan Perban, lalu bergabunglah dengan orang lain dengan cepat.",
  str_story_banner_5020314 = "Sangat bagus. Setelah Anda mendapatkan Perban yang tersisa melalui Combust, Anda harus cukup kuat untuk mengalahkan semua musuh. Ayolah, kamu Eclipsites yang tidak bagus!",
  str_story_banner_5020321 = "A-Tempat apa ini?",
  str_story_banner_5020322 = "Hati-hati, kita pasti terseret ke ruang yang diciptakan oleh senjata peradaban kuno.",
  str_story_banner_5020323 = "Apakah ini \"waktu showdown\" yang baru saja disebutkan?",
  str_story_banner_5020324 = "Itu harus. Persiapkan dirimu!",
  str_story_banner_5020325 = "Ayo pergi. Ini adalah pertempuran terakhir!",
  str_story_banner_5020326 = "Aku sudah berjanji pada Elvis untuk memenuhi keinginannya dan mengaktifkan Windstone kembali.",
  str_story_banner_5020327 = "Jangan coba-coba mendekat!",
  str_story_banner_5020328 = "Elvis, bagaimana kabarmu di sana?",
  str_story_banner_50213211 = "Meskipun semuanya untuk binatang yang menakjubkan, tidakkah menurutmu segalanya terlalu sulit? Bagaimana menurutmu, Kyu?",
  str_story_banner_50213212 = "lihat...",
  str_story_banner_50213213 = "Ya! Tapi aku harus berhasil kali ini untuk mengesankan tuanku!",
  str_story_banner_50213214 = "Lihat!",
  str_story_banner_50213215 = "Wah! Tiba-tiba ada begitu banyak Eclipsites!",
  str_story_banner_50213216 = "Oh, Kyllo pasti akan segera lapar. Habiskan mereka dengan cepat sehingga kita bisa kembali dan berpesta!",
  str_story_banner_50213217 = "Lihat!",
  str_story_banner_50213218 = "Apa ini? Mengapa Tanda Perburuan ada di sana? Betapa anehnya. Mungkinkah itu jatuh secara tidak sengaja ketika saya bermain di Soroz? Ah, lebih baik begini. Ayo pergi, Kyu!",
  str_story_banner_50213219 = "Kami mendatangkan malapetaka, bukan begitu, Kyllo!",
  str_story_banner_50213220 = "Lihat! Lihat!",
  str_story_banner_50213221 = "Air telah disemprotkan ke mana-mana... Oh well, sepertinya masih banyak Eclipsites. Mari kita tempatkan beberapa Tanda Berburu!",
  str_story_banner_50213222 = "Aku tiba-tiba punya ide yang menyenangkan! Kyllo, ayo menyerang!",
  str_story_banner_50213311 = "Panas sekali! Apakah Anda ingin mendinginkan diri?",
  str_story_banner_50213312 = "Apakah Anda melihat Eclipsites di sana? Mereka berdiri di tanda Sunshower saya. Biarkan saya mengaktifkannya untuk membuat mata air yang menyegarkan!",
  str_story_banner_50213313 = "Eclipsites telah diledakkan ke udara! Tralala!",
  str_story_banner_50213314 = "Lihat! Tanda baru akan muncul pada ubin yang memiliki 3 Tanda Sunshower di sekitarnya.",
  str_story_banner_50213315 = "Besar! Ayo kalahkan musuh dengan pistol airku sekarang dalam pertarungan pistol air!",
  str_story_banner_50213401 = "Banyak Eclipsites muncul di teater tanpa nama selama pertunjukan yang luar biasa! Tidak ada yang tahu apakah ini ilusi yang disebabkan oleh hilangnya kewarasan secara bertahap atau ancaman nyata, tetapi Jeno tampaknya tidak terpengaruh sama sekali di atas panggung.",
  str_story_banner_50213402 = "Mari kita sambut tamu kita yang terhormat, PlayerName, untuk menggunakan Origin Deck bersamaku di atas panggung!",
  str_story_banner_50213403 = "Pada saat yang sama, saya juga ingin mengundang Paloma, tamu kami yang lain untuk hari ini!",
  str_story_banner_50213404 = "Aurorian atau Eclipsites, semuanya datang untuk mendukungku!",
  str_story_banner_50213405 = "Pada awalnya, hanya ada cahaya. Lalu, ada matahari, bulan, dan bintang-bintang. Ketika cahaya lembut mereka menyinari kartu, itu melahirkan semua hal. Oleh karena itu, nama \"Asal.\"",
  str_story_banner_50213406 = "Sekarang saatnya untuk menunjukkan kekuatannya.",
  str_story_banner_50213407 = "Pertama, kita perlu mendapatkan banyak kartu. Hati-hati, mereka yang ingin memata-matai rahasia Origin bisa kehilangan akal sehatnya...",
  str_story_banner_50213408 = "Satu kartu lagi. Aku hanya akan kehilangan sedikit kewarasan.",
  str_story_banner_50213409 = "Lagi! Aku bisa mengambil lebih dari ini.",
  str_story_banner_50213410 = "Ini adalah perpustakaan. Jumlah setiap jenis kartu ditampilkan di sini.",
  str_story_banner_50213411 = "Buka di sini untuk masuk ke layar pemilihan Origin Deck.",
  str_story_banner_50213412 = "Kartu Solar, Lunar, dan Cosmic di sebelah kiri dapat diseret ke slot kartu. Efek yang sesuai akan dipicu ketika Kartu Asal ditempatkan di semua 3 slot.",
  str_story_banner_50213413 = "Sekarang silahkan pilih 1 kartu dari masing-masing jenis dan letakkan di slot kartu.",
  str_story_banner_50213414 = "Kombinasi Astronomical Transit terbentuk ketika ketiga kartu memiliki tipe yang berbeda, yang secara permanen meningkatkan ATK anggota di belakang tim.",
  str_story_banner_50213415 = "PlayerName, tolong jadikan Paloma sebagai kapten.",
  str_story_banner_50213416 = "Sekarang masuk ke layar pemilihan Origin Deck.",
  str_story_banner_50213417 = "Mari kita bentuk kombinasi Luminous Cluster kali ini. Tempatkan 3 kartu dengan jenis yang sama ke dalam slot kartu.",
  str_story_banner_50213418 = "Paloma sekarang dapat menerima 2 efek kombinasi Origin Deck, yang akan sangat meningkatkan kekuatan tempurnya. Inilah yang saya unggulkan.",
  str_story_banner_50213419 = "Ada 1 kombinasi lagi. Ingatlah untuk menggunakannya ketika Anda ingin memulihkan kewarasan Anda.",
  str_story_banner_50213420 = "PlayerName, panggung sekarang milik Anda. Pertahankan pertunjukan dengan penampilan apa pun yang Anda inginkan.",
  str_story_banner_507401 = "Tenang, Casta!",
  str_story_banner_507402 = "Apa kau serius menyuruhku untuk tenang dengan pembunuh Matilda tepat di depanku?!",
  str_story_banner_507403 = "Aku akan mengatakannya untuk terakhir kalinya, menyingkirlah!",
  str_story_banner_507404 = "Sepertinya kita harus melakukan ini dengan cara yang sulit...",
  str_story_banner_50223211 = "Hati-Hati! Sebuah Eclipsite menyergap kita di sana.",
  str_story_banner_50223212 = "Biarkan aku menyiapkan senjataku, lalu kita bisa lebih dekat dan mengejutkan mereka dengan apa yang kita punya.",
  str_story_banner_50223213 = "Ubin hijau dan Ubin yang Ditingkatkan dapat membantu saya menemukan titik lemah musuh. Untuk setiap 6 titik yang ditemukan, serangan berikut saya akan menjadi lebih kuat.",
  str_story_banner_5022321301 = "Jika sebuah ubin memenuhi kedua kondisi tersebut, saya dapat menemukan titik lemah dua kali lipat, jadi cobalah untuk bergerak di sepanjang jalur kedua ubin tersebut.",
  str_story_banner_50223214 = "Batas Titik Pemicu tercapai! Senjata panas lagi. Gunakan Skill Aktif Anda lagi dan singkirkan monster di sekitarnya!",
  str_story_banner_50223111 = "Masih banyak musuh, tapi mereka belum berada dalam jangkauan Heavy Fire-ku...",
  str_story_banner_50223112 = "Tanpa garis serangan yang jelas, tidak banyak yang bisa saya lakukan.",
  str_story_banner_50223113 = "Heh... Jika tidak ada garis serang, kita harus membuatnya sendiri! Ekspansi peluru!",
  str_story_banner_50223114 = "Musuh tidak punya tempat untuk lari! Saatnya memusnahkan mereka dengan Heavy Fire-ku!",
  str_story_banner_41000111 = "Menurut intel... Ini seharusnya kota bawah–Achoo! Sepertinya tidak ada yang datang ke sini dalam beberapa saat, jadi harap berhati-hati saat menjelajah.",
  str_story_banner_41000112 = "Itu disembunyikan dengan sangat baik. Kami akan kesulitan menemukannya jika Siobhan tidak ada di sini.",
  str_story_banner_41000113 = "Saya pikir saya mencium sesuatu yang menjijikkan! Meong!",
  str_story_banner_41000114 = "Hai! Eclipsites di sini sepertinya telah menguasai skill baru yang aneh!!!",
  str_story_banner_41000115 = "Itu adalah Wormgate. Beginilah cara mereka datang dan menyerang bagian bawah kota.",
  str_story_banner_41000116 = "Kedengarannya berbahaya, meong.",
  str_story_banner_41000117 = "Sepertinya Eclipsites terus muncul darinya, jadi kita harus berhati-hati.",
  str_story_banner_41000121 = "Satu, dua... Ada banyak hal yang akan datang.",
  str_story_banner_41000122 = "Mari kita temukan medan yang menguntungkan sebelum mereka muncul.",
  str_story_banner_41000123 = "Mari kita pergi ke sana bersama-sama dulu!",
  str_story_banner_41000131 = "Untung kita datang ke sini, kalau tidak kita akan dikelilingi oleh Eclipsites itu.",
  str_story_banner_41000132 = "Ada terlalu banyak Eclipsites. Kita harus melawan mereka dan mencari jalan keluar.",
  str_story_banner_41000133 = "Biarkan pertempuran dimulai!",
  str_story_banner_41000141 = "Ahhh! Tenggorokan saya!",
  str_story_banner_41000142 = "Apakah ini... gas berbahaya yang disebutkan dalam kontrak?",
  str_story_banner_41000143 = "Jangan khawatir. Masih banyak waktu sampai itu membuat kita marah.",
  str_story_banner_41000151 = "Saya pikir saya melihat jalan keluar.",
  str_story_banner_41000152 = "Menurut cetak biru sebelumnya, jalan itu seharusnya mengarah ke ruangan dengan alat ventilasi!",
  str_story_banner_41000161 = "Sepertinya jalan di depan tidak akan mudah untuk dilalui...",
  str_story_banner_41000162 = "Ini adalah waktu yang tepat untuk mengungkit PlayerNameperalatan terbaru! Meong!",
  str_story_banner_41000163 = "Caltrop mengamuk!",
  str_story_banner_41000164 = "Anda benar-benar membawa itu. Saya berpikir untuk mempelajarinya nanti ...",
  str_story_banner_41000165 = "Ahem... Pokoknya, ayo PlayerName menggunakannya untuk mengubah Lumina. Kami akan berlari ke sana dalam satu tarikan napas!",
  str_story_banner_41000171 = "PlayerName, itu cukup sederhana untuk digunakan. Buang saja, meong! Bahkan Revy dapat menggunakannya dengan benar!",
  str_story_banner_41000172 = "Baguslah kalau begitu.",
  str_story_banner_41000173 = "Apa yang Anda maksud dengan \"bahkan Revy dapat menggunakannya dengan benar\"...",
  str_story_banner_41000181 = "Tampaknya berhasil! Sekarang, PlayerName, kami membutuhkan Anda untuk membimbing kami!",
  str_story_banner_41000211 = "Serahkan saja sisanya pada kami, Vice.",
  str_story_banner_41000212 = "Baiklah, saya percaya Anda untuk melindungi PlayerName.",
  str_story_banner_41000213 = "Tenang, semuanya akan baik-baik saja dengan Tech Officer Gronru dan Migard di sini. Kalian istirahatlah untuk saat ini.",
  str_story_banner_41000214 = "Peringatan. Batu aneh terdeteksi di dekatnya.",
  str_story_banner_41000215 = "Itu pasti Batu Halo... Tapi apa yang dilakukannya di sini? Bukankah seharusnya itu dikunci di tingkat terendah Lab Penelitian?",
  str_story_banner_41000216 = "Mungkinkah seseorang sudah pernah ke sini?",
  str_story_banner_41000217 = "Itu tidak mungkin. Kemungkinan besar dibawa ke sini secara tidak sengaja oleh Eclipsite. Tanpa ada yang menyuruh mereka, mereka hanya bergerak dan bertindak tanpa pandang bulu.",
  str_story_banner_41000221 = "Yah, untungnya mereka ada di sini. Hehe, mari kita aktifkan benda ini!",
  str_story_banner_41000231 = "Tampaknya cukup berguna. Dengan memproduksinya secara massal, kami dapat menyelesaikan banyak masalah kami di medan perang...",
  str_story_banner_41000232 = "Maaf untuk memberitahu Anda, Chief, tapi saya pikir ini masih dalam tahap awal penelitian. Sebagai peninggalan peradaban kuno, itu agak tidak stabil.",
  str_story_banner_41000233 = "Betul sekali! Saya menyadari bahwa jika Lumina terlalu rumit, itu akan gagal!",
  str_story_banner_41000241 = "Peringatan. Musuh mendekat.",
  str_story_banner_41000242 = "Kita benar-benar tidak bisa istirahat, kan?",
  str_story_banner_41000243 = "Paksa mereka kembali untuk saat ini! Semuanya, serang!",
  str_story_banner_41000251 = "Peringatan. Batu yang tidak menyenangkan terdeteksi.",
  str_story_banner_41000252 = "Kita sudah tahu itu. Apakah Anda akan mengulangi diri sendiri setiap saat?",
  str_story_banner_41000253 = "Batu itu tampaknya menekan kemampuan kita... Perhatikan baik-baik, PlayerName!",
  str_story_banner_41000261 = "Dikonfirmasi. Tidak dapat menggunakan keterampilan tertentu.",
  str_story_banner_41000262 = "Itu benar...",
  str_story_banner_41000263 = "Jika ini adalah semacam permainan, langkah terbaik kita adalah menjauh darinya!",
  str_story_banner_41000271 = "Aku merasa lebih baik sekarang. Bahkan udara tampak jauh lebih jernih.",
  str_story_banner_41000272 = "Tapi dengan batu yang menghalangi jalan, kita akan kesulitan membuat kemajuan.",
  str_story_banner_41000273 = "Menarik. Sini, biarkan aku mencoba sesuatu.",
  str_story_banner_41000281 = "Wah! Sepertinya selama kita berdiri di luar area efeknya, kekuatan kita tidak terpengaruh!",
  str_story_banner_41000282 = "Memang. Saya memastikan untuk menjaga jarak tertentu dari itu sekarang sebelum menyerang.",
  str_story_banner_41000291 = "Di sana!",
  str_story_banner_41000292 = "Sepertinya cara ini mengarah ke ventilator. Kita akan melewati lantai ini!",
  str_story_banner_41000293 = "Sigh... Bisakah kamu berhenti memperlakukan pertempuran seperti ini adalah permainan? Sudahlah. PlayerName, tolong bawa kami ke sana dengan cepat.",
  str_story_banner_11200202 = "PlayerName, kami telah menerima permintaan dari Federasi Illumina untuk menyelidiki Undercity.",
  str_story_banner_11400101 = "Laboratorium Axelia telah dimulai! Kumpulkan bagian memo dan bantu Axelia menyelesaikan eksperimennya!",
  str_story_banner_11500401 = "Navigator, sebuah sarang muncul di dekat Wilayah Rahasia, dan sejumlah besar Eclipsites telah terlihat. Kita harus berurusan dengan mereka secepat mungkin!",
  str_story_banner_11500701 = "Navigator! Segerombolan besar Eclipsites telah muncul! Satu-satunya cara kita muncul sebagai pemenang di sini hari ini adalah jika kita menghalau semua gelombang Eclipsite!",
  str_story_banner_11500702 = "Kami telah menyelesaikan gelombang pertama Eclipsites! Setiap kali Anda melawan gelombang Eclipsites, Anda akan mendapatkan hadiah Relik untuk memperkuat kekuatan tempur Anda dalam pertempuran berikutnya. Sekarang, pilih Relik!",
  str_story_banner_11500703 = "Anda telah mengalahkan bos! Rekan baru dapat bergabung dengan tim Anda untuk membantu Anda dalam pertempuran. Sekarang, pilih seorang Aurorian!",
  str_story_banner_11500704 = "Seorang Aurorian yang bergabung dengan Anda dalam pertempuran dapat menghubungkan ubin untuk bertarung, meluncurkan Kombo Rantai, dan menggunakan Keterampilan Aktif, sama seperti anggota tim Anda yang lain.",
  str_story_banner_11500705 = "Anda hanya dapat maju setelah mengambil cukup Eclipsites!",
  str_story_banner_11500706 = "Ini akan menjadi pertarungan yang sulit... Tapi jangan khawatir—dalam pertempuran ini, kamu akan memiliki rekan Aurorian yang kuat untuk membantumu muncul sebagai pemenang!",
  str_story_banner_11500707 = "Sekarang, saatnya bersiap-siap untuk bertarung!",
  str_story_banner_523500201 = "Saatnya melapor ke Nona Nina. Semuanya berjalan baik dengan rumah hantu untuk saat ini.",
  str_story_banner_523500202 = "Saya ingin tahu bagaimana kabar Nona Nina baru-baru ini? Sanae harus merawatnya dengan baik.",
  str_story_banner_523500203 = "Hmm... Gerhana, makhluk yang menyedihkan. Sayang sekali saya tidak punya waktu untuk menidurkan mereka sekarang.",
  str_story_banner_523500204 = "Kepala pelayan yang sempurna tidak boleh terlambat. Aku harus bergegas.",
  str_story_banner_523500301 = "Membuatku pergi ke pinggiran kota untuk menemukan dompet yang hilang atau semacamnya—mengapa Dayna masih memperlakukanku seperti anak kecil?",
  str_story_banner_523500302 = "Dompet... Dompet... Ah! Ini dia!",
  str_story_banner_523500303 = "Hehe, aku harus memintanya untuk tugas lain setelah aku kembali. Aku akan menjadi jagoan sejati suatu hari nanti jika aku terus begini!",
  str_story_banner_523500304 = "Apa!!?? Kapan begitu banyak Eclipsites muncul di belakangku?!",
  str_story_banner_523500305 = "Tidak masalah! Sadi! Lakukan apa yang biasa kamu lakukan selama latihan...Lakukan apa yang biasa kamu lakukan saat latihan...Lakukan apa yang biasa kamu lakukan saat latihan...",
  str_story_banner_523500306 = "Terbang—Bola—!",
  str_story_banner_523500307 = "Itu berhasil! Saya selangkah lebih dekat untuk menjadi petualang! Aku akan mengurusmu dengan cepat dan memberi tahu Dayna semua tentang gerakan kerenku!",
  str_story_banner_523500101 = "Saatnya melapor ke Nona Nina. Semuanya berjalan baik dengan rumah hantu untuk saat ini.",
  str_story_banner_523500102 = "Wah! Apa yang salah dengan tempat ini? Kenapa tiba-tiba ada Eclipsite di sekitarku? Ini menakutkan!",
  str_story_banner_523500103 = "Tetap tenang... Lihat, ada barisan mempesona lainnya di sana.",
  str_story_banner_523500104 = "Saya bisa teleport ke sana dulu, sesuaikan posisi saya, dan hancurkan mereka!",
  str_story_banner_523500105 = "Tadaa! Tonton entri saya yang mempesona!",
  str_story_banner_523500106 = "Jalur ini memungkinkan kita bergerak di antara dua larik yang mempesona. Kami akan memanggil array mempesona baru saat menyerang Eclipsites dan menghubungkan dua array mempesona ini.",
  str_story_banner_523500107 = "Array yang mempesona telah menjadi lebih besar. Mari kita hancurkan Eclipsites yang menakutkan ini sekarang.",
  str_story_banner_524300101 = "Ini buruk! Tidak hanya pasukan yang dipisahkan, sekarang kami juga memiliki Eclipsites.",
  str_story_banner_524300102 = "Kami hanya akan menyebutnya perubahan suasana hati.",
  str_story_banner_524300103 = "Axelia, giliranmu!",
  str_story_banner_524300104 = "Salinan. Mengaktifkan Modul Otoritas. Rute optimal dihitung.",
  str_story_banner_524300105 = "Aku akan menebus kurangnya penyembuhan dan daya tembak.",
  str_story_banner_524300106 = "Siaga, Grand Marshal.",
  str_story_banner_10130701 = "Saya pikir kita sudah memiliki kesimpulan!",
  str_story_banner_10130702 = "Simulator bekerja jauh melebihi harapan kami!",
  str_story_banner_10130703 = "PlayerName tampaknya menjadi lebih kuat.",
  str_story_banner_10130704 = "Itu hanya bisa dikonfirmasi setelahnya PlayerName terputus dari Colossus dan mengakhiri percobaan.",
  str_story_banner_10130705 = "Lagi pula, kita masih perlu memeriksa data fungsi fisiknya.",
  str_story_banner_10130706 = "Mendesis-!!!",
  str_story_banner_10130707 = "Bagaimana mungkin?!",
  str_story_banner_10130708 = "T-Data medan perang kuno pasti rusak!",
  str_story_banner_10130709 = "Peneliti, dengarkan aku! Hentikan percobaan segera!",
  str_story_banner_10131201 = "Merasakan getaran dari tanah.",
  str_story_banner_10131202 = "Disintegrasi yang akan datang akan menyentuh mantel, menyebabkan terkilir dan retaknya permukaan.",
  str_story_banner_10131203 = "Medan perang virtual akan mencapai titik tidak bisa kembali.",
  str_story_banner_10131204 = "Saya akan melakukan hitungan mundur terakhir untuk Anda.",
  str_story_banner_524300201 = "Huff... The Eclipsites terus berdatangan. Apa mereka hanya mencoba membuatku lelah? Dan aku terluka...",
  str_story_banner_524300202 = "Tapi saya tidak akan dikalahkan oleh taktik mereka.",
  str_story_banner_524300203 = "Pilih jalur terpanjang yang bisa Anda tempuh agar saya bisa menusuk tubuh mereka dengan Australis Spears terlebih dahulu.",
  str_story_banner_524300204 = "Persiapan awal telah selesai. Memulai perawatan.",
  str_story_banner_525300201 = "*Menguap* Sepertinya ada Eclipsites yang masuk.",
  str_story_banner_525300202 = "Eclipse elit itu melindungi mereka dari kehancuran.",
  str_story_banner_525300203 = "Heh... Kamu pikir kamu aman bersembunyi di sana?",
  str_story_banner_525300204 = "Menyerang! Semua orang! Bunuh Eclipsite elit itu dulu!",
  str_story_banner_525400301 = "Oh! Lola, saya berjanji untuk menemani Anda selama pelatihan khusus Anda selama Anda berbagi semua gosip terbaru dengan saya!",
  str_story_banner_525400302 = "Terima kasih banyak! Beri aku sebotol madu favoritku juga!",
  str_story_banner_525400303 = "Sepakat! Lihat, ada yang sangat sulit di sana.",
  str_story_banner_525400304 = "Jangan terburu-buru! Saya akan membuatnya mengungkap kelemahannya terlebih dahulu, dan kemudian kita akan membongkarnya!",
  str_story_banner_525400305 = "Saya merasa akurasi saya meningkat. Kamera Anda luar biasa!",
  str_story_banner_525400306 = "Eclipsites itu telah terkena Tanda Pengintaian! Jika kamu menyerang mereka dengan Chain Combo sekarang, itu akan memberikan lebih banyak damage!",
  str_story_banner_5254002011 = "Dari mana semua musuh ini berasal!? Mari kita tampilkan acara ini di jalan!",
  str_story_banner_5254002012 = "Mereka bahkan tidak akan tahu apa yang menimpa mereka!",
  str_story_banner_5254002013 = "Modus perang! Pergeseran Sopran!",
  str_story_banner_5254002014 = "Rute ini melalui koneksi ubin yang ditingkatkan seharusnya berfungsi! Abaikan barikade musuh dan cepatlah ke atas panggung! Saya perlu menyapa penggemar saya dalam performa terbaik!",
  str_story_banner_52630021 = "Sepertinya aku sudah kembali ke medan perang lagi.",
  str_story_banner_52630022 = "Meskipun mobilitas adalah suatu masalah, saya akan mencoba yang terbaik untuk membantu Anda.",
  str_story_banner_52630023 = "Dan dengan demikian, Eclipsite untuk sementara berada di bawah kekuasaan Api Leluhur saya.",
  str_story_banner_52630024 = "Tolong, gunakan keahlian saya untuk memindahkan Eclipsite. Api Leluhur akan membuka jalan.",
  str_story_banner_52630025 = "Kekuatan ajaib seperti itu! Ceritakan kepada kami sebuah kisah tentang masa lalu ketika semuanya selesai.",
  str_story_banner_52630031 = "Sakit sekali... PlayerName, Anda tidak memberi tahu saya bahwa ada Eclipsites yang menyebalkan seperti ini!",
  str_story_banner_52630032 = "Jika kita menyerang secara langsung, Eclipsites lainnya akan pulih.",
  str_story_banner_52630033 = "Serahkan padaku... Aku punya obat yang sempurna!",
  str_story_banner_52630034 = "Sekarang orang ini tidak akan kalah di babak ini. Hancurkan dirimu, orang tua!",
  str_story_banner_52630035 = "Kerja yang baik! Saya tidak punya ikan di sini, tapi saya akan membiarkan Anda mencoba kadal bakar khusus nanti.",
  str_story_banner_52630011 = "Segerombolan Eclipsites telah naik ke kapal. Jangan panik.",
  str_story_banner_52630012 = "Gunakan Chain Combo sebanyak yang Anda bisa untuk menyalakan Serpent Flare saya.",
  str_story_banner_52630013 = "Setelah menyalakan tiga Serpent Flare, saya bisa menggunakan Skill Aktif saya yang kuat untuk melepaskan amarah laut ke arah mereka!",
  str_story_banner_52630014 = "Nyalakan Serpent Flare, lanjutkan membuat kombo, lalu nyalakan sisanya! Serpent Flares dapat lebih mudah disinari selama Waktu Aurora.",
  str_story_banner_527200401 = "Navigator Kecil, giliranmu untuk memerintahku—maksudku, Bullock 8.",
  str_story_banner_527200402 = "Cintaku yang manis! Jangan hancurkan dia!",
  str_story_banner_527200403 = "Dia benar-benar menawan, menarik begitu banyak Eclipsites di sini...",
  str_story_banner_527200404 = "Jadi, tugas menghilangkan ampas ini jatuh ke tangan Anda!",
  str_story_banner_527200405 = "Dia berbeda dari Colossus Anda! Dia juga bisa bertarung!",
  str_story_banner_527200406 = "Mobil balap ini memiliki semua jenis gadget dan jebakan yang dirancang untuk mengubah bajingan itu menjadi butiran pasir!",
  str_story_banner_527200411 = "Ha ha! Tak lama lagi, sampah ini akan berubah menjadi debu! Memikirkannya saja membuatku merasa lebih baik.",
  str_story_banner_527200412 = "Setelah merawat kotoran ini, kekasih yang menawan ini akan menjadi seperti hujan! Anda dapat mengatur perangkap sebanyak yang Anda inginkan!",
  str_story_banner_527200413 = "Bullock 8 dapat memulihkan 1 poin Energi setiap putaran. Tentu saja, membersihkan sampah ini juga dapat mengakumulasi Energi untuknya.",
  str_story_banner_527200414 = "Tentu saja, tidak akan ada terlalu banyak jebakan! Lagi pula, semuanya ada batasnya, dan cintaku yang manis bukanlah salah satu dari truk Illumina jelek yang besar itu...",
  str_story_banner_527200415 = "Harap dicatat bahwa dia hanya dapat menyebarkan hingga 6 jebakan.",
  str_story_banner_527200416 = "Tetap saja, aku bisa meminta cintaku yang manis untuk menghilangkan perangkap itu, dan tidak ada biaya apapun!",
  str_story_banner_527200421 = "Slimeball menjijikkan ini... Ada sesuatu yang aneh tentang itu... Sepertinya dia sama sekali tidak takut dengan jebakan itu!",
  str_story_banner_527200422 = "Dan skill menjijikkannya bisa menghancurkan jebakan! Manis Caelestite saya, hati-hati!",
  str_story_banner_52740011 = "Dengan serius? Aku anggota senior sekarang. Mengapa saya masih harus berurusan dengan hal ini?",
  str_story_banner_52740012 = "Saya benar-benar ingin kembali ke bacaan saya. Mari kita singkirkan gangguan ini secepatnya.",
  str_story_banner_52740013 = "Setiap kali Anda mengetuk ubin yang disempurnakan, Anda dapat memilih titik pendaratan lainnya.",
  str_story_banner_52740014 = "Dengan begitu, Anda dapat menyerap ubin yang ditingkatkan dengan Skill Aktif dan meningkatkan kerusakan akhir dari Skill Peralatan Anda. Ayo bergerak!",
  str_story_banner_52740021 = "Saya akan memberikan pencarian pengiriman ini tembakan terbaik saya!",
  str_story_banner_52740022 = "Ssst... lihat Eclipsites di sekitar kita? Mari singkirkan mereka sebelum berangkat, hanya untuk amannya.",
  str_story_banner_52740023 = "Bukan masalah!",
  str_story_banner_52740024 = "Dekati mereka dengan keterampilan teleportasi, dan aku akan menangani serangannya!",
  str_story_banner_52840011 = "PlayerName, Saya benar-benar minta maaf karena harus meminta Anda untuk membantu saya menangani hal ini.",
  str_story_banner_52840012 = "Itu karena... aku hanya tidur... 12 jam...",
  str_story_banner_52840013 = "Zzzzzzz...",
  str_story_banner_52840014 = "Jangan khawatir, Tina bisa melawan bahkan ketika dia sedang tidur.",
  str_story_banner_52840015 = "Metode pemilihan Skill Aktif Tina berbeda dengan Aurorian lainnya. Pertama, Anda perlu menentukan jalur pergerakannya dengan menghubungkan ubin.",
  str_story_banner_52840016 = "Setelah menentukan jalannya, Tina akan berjalan sambil tidur di sepanjang rute yang dipilih, mengubah warna ubin di sepanjang jalurnya, dan pada akhirnya akan kembali ke titik awalnya.",
  str_story_banner_52840017 = "Saat menghubungkan ubin, Anda juga dapat menghubungkan ubin musuh sebagai titik akhir Tina tanpa menghabiskan jumlah ubin yang dapat Anda sambungkan.",
  str_story_banner_52840018 = "Dalam situasi ini, Tina akan berhenti di ubin sebelum titik akhir dan memberikan kerusakan pada musuh.",
  str_story_banner_52840019 = "Gerhana! Beraninya kau menunjukkan wajah kotormu di Lumopolis! Ini sama sekali tidak bisa dimaafkan!",
  str_story_banner_52840020 = "Pertama tingkatkan kecepatan senjata hingga maksimal, lalu luncurkan skill!",
  str_story_banner_52840021 = "Bala bantuan? Sepertinya kita harus menggunakan beberapa keterampilan nyata di sini.",
  str_story_banner_52840022 = "Gunakan Skill Aktif! Lepaskan semua Semangat dan musnahkan mereka!",
  str_story_banner_52840023 = "Beraninya Eclipsites yang kotor ini mengotori Lumopolis! Kita harus memurnikan mereka!",
  str_story_banner_52840024 = "Orang biasa, aku akan meninggalkan Eclipsites yang lemah itu di sana di tanganmu.",
  str_story_banner_52840025 = "Aku akan membersihkan sisanya.",
  str_story_banner_52840026 = "Saya telah mengumpulkan kekuatan yang cukup. Sekarang, giliranku untuk bertarung.",
  str_story_banner_5299001 = "I-Itu mobil rusak itu lagi! Apakah Anda ingat bagaimana kita p-memisahkannya bersama terakhir kali?",
  str_story_banner_5299002 = "Pertama, kalahkan itu Chainsaw Rick b-menghalangi jalan!",
  str_story_banner_5299003 = "<color=#FFB400>Mengetuk Aurorian musuh akan menunjukkan aksi mereka selanjutnya.</color>",
  str_story_banner_5299004 = "<color=#FFB400>Aurorian biasanya menargetkan unit musuh terdekat.</color>",
  str_story_banner_5299005 = [[
Tapi mereka <color=#FFB400>hanya dapat bergerak di ubin elemennya sendiri!</color>
Jaga jarak-d Anda dan lakukan yang terbaik untuk tidak membiarkan mereka menyakiti kita.]],
  str_story_banner_5299006 = [[
I-Ini di sini menunjukkan ATK dan HP musuh,
dan menurut saya ini cara yang cukup mudah untuk menilai apakah Anda siap menghadapi tantangan.]],
  str_story_banner_5299007 = "Ayo beraksi!",
  str_story_banner_5299008 = "Luar biasa!",
  str_story_banner_5299009 = [[
Baiklah, aku dan Darkwasp itu sekarang sedang menunggu perintahmu.
(K-Kalau saja aku bisa membiarkan Darkwasp maju dan mencari tempat untuk bersembunyi...)]],
  str_story_banner_5299010 = [[
O-Oh ya! Lord Augean telah menyempurnakan kemampuan baru! <color=#FFB400>Saat menerima kerusakan jarak dekat, dia sekarang dapat melakukan serangan balik kepada penyerang</color>!
Pastikan untuk memanfaatkan keahlian khusus ini!]],
  str_story_banner_5299011 = [[
O-Oh, tidak!
Saya baru saja mendengar bahwa teman kami yang bersembunyi di Lumopolis telah ditemukan dan melawan para penjaga!
K-Kita harus bergegas dan membantu mereka!]],
  str_story_banner_5299012 = "Mereka cukup jauh, jadi coba gunakan <color=#FFB400>lubang cacing</color> di depan untuk sampai ke sana lebih cepat.",
  str_story_banner_5299013 = [[
Tapi masih banyak Aurorian yang menghalangi jalan...
Apakah Anda ingin menghindarinya atau tidak, itu terserah Anda.]],
  str_story_banner_5299014 = [[
Barbara!
Kudengar dia bisa <color=#FFB400>menyerang dan mengejutkan kami</color>... Dia t-menakutkan!]],
  str_story_banner_5299015 = "T-Tapi kami memiliki sekutu yang kuat untuk membantu kami—Thumper!\nGemuruh bisa <color=#FFB400>mengetuk target kembali 2 ubin</color>!",
  str_story_banner_5299016 = [[
Ini tidak hanya bekerja melawan Aurorian, Anda juga dapat menggunakannya pada sekutu Eclipsite Anda!
Kadang-kadang, itu bahkan memberi Anda beberapa kejutan strategis ...]],
  str_story_banner_5299017 = "Cobalah!",
  str_story_banner_5299018 = "Ini sepertinya situasi yang mirip dengan yang sebelumnya, tetapi tanpa kerusakan perangkap.",
  str_story_banner_5299019 = "K-Kamu harus mulai berpikir tentang bagaimana kamu akan menghadapinya Barbara...",
  str_story_banner_5299020 = "<color=#FFB400>Mungkin Thumper bisa mendorong kita maju?</color>",
  str_story_banner_5299021 = [[
Akhirnya, kami tiba di LL-Lumopolis!
Ayo kalahkan Penjaga Lumo ini bersama sekutu Eclipsite kita!]],
  str_story_banner_5299022 = "<color=#FFB400>Aphonic Assistant dapat memulihkan HP sekutu Eclipsite kita dalam jangkauan</color>, memberikan dukungan vital!",
  str_story_banner_5299023 = "II-Itu dia! Pria yang bersembunyi di lumopolis terdalam\n—<color=#FFB400>Schwartz!</color>",
  str_story_banner_5299024 = "A-aku takut, t-tapi kita tidak bisa mundur...",
  str_story_banner_5299025 = "T-Tolong j-menyerah saja! ... Apakah saya terdengar seperti maksud saya bisnis?",
  str_story_banner_5299026 = [[
Ngomong-ngomong, ayo serahkan ini pada Lord Augean. Bagi saya...
Saya akan menyemangati semua orang dari belakang! Kamu... Kamu bisa melakukannya!]],
  str_story_banner_52940011 = "Sial... Aku terluka.",
  str_story_banner_52940012 = "Beberapa dari mereka masih mengejarku? Tidak, orang-orang ini menunggu di sini untuk menyergapku.",
  str_story_banner_52940013 = "Sepertinya mereka berusaha keras untuk menyiapkan rintangan itu.",
  str_story_banner_52940014 = "Tapi mereka terlalu naif jika berpikir itu akan menghentikanku.",
  str_story_banner_52940021 = "Awas, ada Eclipsites di depan.",
  str_story_banner_52940022 = "Ubin diagonal di depan adalah tempat yang lebih baik untuk menyerang. Akan sangat bagus jika saya bisa pindah ke sana.",
  str_story_banner_52940023 = "Jangan khawatir, saya bisa menggunakan Varian Keterampilan Aktif saya untuk memindahkan kita ke sana.",
  str_story_banner_52940024 = "Varian Skill Aktif adalah variasi dari Skill Aktif yang memiliki efek sedikit berbeda. Casting itu akan mempengaruhi jumlah cooldown dari Skill Aktif berikutnya.",
  str_story_banner_52940025 = "Biarkan torrent saya membersihkan semua kejahatan!",
  str_story_banner_11900701 = "Anda dapat melakukan penyempurnaan peralatan di sini. Mari kita lihat beberapa hal yang dapat Anda lakukan!",
  str_story_banner_11900801 = "Anda dapat melakukan penyempurnaan peralatan di sini. Mari kita lihat beberapa hal yang dapat Anda lakukan!",
  str_story_banner_29052011 = [[
Dapatkah Anda merasakan kematian datang untuk Anda?
Rasakan seperti apa kematian bagi diri Anda sendiri.]],
  str_story_banner_29052012 = "Ini bukan apa-apa...!",
  str_story_banner_29052013 = "Di sinilah Anda akan mati!",
  str_story_banner_29052014 = "Perlawananmu sia-sia.",
  str_story_banner_29052015 = "Tidak tidak! Ini tidak mungkin!",
  str_story_banner_53040011 = "Apa aku masuk terlalu dalam? Saya sepertinya dikelilingi oleh Eclipsites.",
  str_story_banner_53040012 = "Jangan panik, kita perlu memikirkan dengan tenang cara untuk keluar.",
  str_story_banner_53040013 = "Gunakan Skill Aktif untuk menerobos pengepungan di atas terlebih dahulu.",
  str_story_banner_53040014 = "Lemah.",
  str_story_banner_53040015 = "Ada banyak ubin yang ditingkatkan di sepanjang jalan di sebelah kanan. Mengambilnya akan meningkatkan efek keterampilanku. Mari ambil rute ini dan singkirkan Eclipsites yang tersisa.",
  str_story_banner_53040016 = "Aku akan mengalahkan musuh di jalanku dengan pedangku. Tarik pedangmu!",
  str_story_banner_53040021 = "Jarang memiliki kesempatan untuk bertarung berdampingan dengan Kolonel Yingel.",
  str_story_banner_53040022 = "Ada banyak musuh, tolong buatkan strategi untuk kami, Kolonel Yingel.",
  str_story_banner_53040023 = "Tentu. Saya akan membimbing semua orang ke depan.",
  str_story_banner_53040024 = "Kita seharusnya bisa menyerang Eclipsites di kejauhan sekarang. Mari kita selesaikan ini dengan cepat.",
  str_story_banner_53040031 = "Berdasarkan apa yang telah kita pelajari sejauh ini, ada banyak Eclipsites yang tersebar di seluruh area. Hanya bergegas keluar dan menyerang mereka tidak akan membantu.",
  str_story_banner_53040032 = "Inilah yang saya pikirkan: jika kita menggunakan pendekatan Ode to the Depths, peluang kita untuk menang adalah 99%.",
  str_story_banner_53040033 = "Kita bisa menggunakan Darkness Cometh karena mereka berkumpul di satu tempat.",
  str_story_banner_53040034 = "Berdasarkan informasi yang kami miliki, mendekati musuh dengan cepat dapat memberi kami peluang 90% untuk menang.",
  str_story_banner_53040035 = "Saya akan menggunakan Ode to the Depths untuk menutup jarak.",
  str_story_banner_53130031 = "Saya memiliki perasaan bahwa saya dapat menemukan beberapa rahasia ramalan yang menakjubkan di sini. Saya sangat bersemangat!",
  str_story_banner_53130032 = "Tunggu apa? Kenapa ada begitu banyak Eclipsites sekarang? Mereka tidak ada di ramalan kemarin!",
  str_story_banner_53130033 = "Sudahlah! Kitab Ramalan akan punya solusinya!",
  str_story_banner_53130034 = "Ini terbakar? Yah, setidaknya kita bisa melihat jejak cahayanya!",
  str_story_banner_53130021 = "The Eclipsites akan datang... Aku harus menjaga tempat ini. Ini adalah tanggung jawab saya.",
  str_story_banner_53130022 = "Orang yang memancarkan aura yang sangat jahat pastilah pemimpin Eclipsite. Serangan normal tidak akan berpengaruh banyak padanya.",
  str_story_banner_53130023 = "Tapi pedangku bukanlah senjata biasa. Potong kepala ular dan sisa tubuhnya akan mengikuti.",
  str_story_banner_53130024 = "Beberapa Pisau Dawn telah tersebar. Ini adalah kesempatan yang kami tunggu-tunggu.",
  str_story_banner_53130025 = " Gunakan Darkness Shattered untuk mengambilnya—itu akan memperkuat serangan normalku dan mengurangi cooldown Days Without End.",
  str_story_banner_53130011 = "Urgh... Aku kena, dan masih banyak Eclipsites.",
  str_story_banner_53130012 = "Jangan khawatir! Aku benar-benar merasa jauh lebih kuat sekarang.",
  str_story_banner_53130013 = "Eclipsites mengelilingi kita? Tidak apa-apa, gunakan saja The Summoning saya untuk melenyapkan mereka!",
  str_story_banner_53130014 = "Ini adalah kekuatan Pemanggilan... Perisainya dapat mencegah Eclipsites itu menyentuhku.",
  str_story_banner_53130015 = "Lihat, perisainya telah bekerja. Sudah waktunya bagi kita untuk melancarkan serangan balik.",
  str_story_banner_53130016 = "Jangan lupa gunakan Kelahiran Baba Yaga. Perisai yang diberikannya akan membuat kita tak terkalahkan.",
  str_story_banner_53191011 = "Selamat datang di Pelatihan Luminatics hari ini! Jangan khawatir, ini tidak sesulit kedengarannya!",
  str_story_banner_53191012 = "Ini adalah kursus pelatihan khusus yang dirancang khusus untuk meningkatkan kemampuan Anda memandu jejak cahaya, jadi Anda tidak akan melihat musuh bermunculan di sini, yakinlah!",
  str_story_banner_53191013 = "Ketuk ubin di lapangan untuk memilih ubin dari elemen yang sama yang terhubung dengannya.",
  str_story_banner_53191021 = "Setelah memilih ubin, ketuk lagi area yang dipilih untuk menghapusnya.",
  str_story_banner_53191031 = "Ketika jumlah ubin yang Anda singkirkan mencapai skor tertinggi, Anda akan menyelesaikan tantangan ini!",
  str_story_banner_53191032 = "Sekarang semuanya terserah Anda, Navigator! Cobalah sendiri!",
  str_story_banner_53192011 = "Lihat, ada banyak ubin Biru di lapangan, tapi terputus di tengah.",
  str_story_banner_53192021 = "Jadi begini caranya cahaya mengalir? Tunggu! Saya punya ide!",
  str_story_banner_53192031 = "Lihat! Kami memiliki begitu banyak ubin Biru yang terhubung sekarang! Hapus mereka bersama-sama!",
  str_story_banner_53192041 = "Setelah menghapusnya, skor Anda mencapai kondisi peringkat, dan sekarang Anda memiliki kesempatan untuk menggunakan Raging Caltrops.",
  str_story_banner_53192051 = "Raging Caltrops dapat mengonversi dua ubin berwarna! Cobalah sendiri!",
  str_story_banner_53193011 = "Dua anggota tim baru telah tiba, dan mereka dapat mengonversi lebih banyak ubin Biru.",
  str_story_banner_53193012 = "Navigator, saatnya Anda mengambil kendali!",
  str_story_banner_53194011 = "Kami memiliki beberapa konten pelatihan baru untuk Anda... Lihat! Ubin Rune telah muncul di lapangan!",
  str_story_banner_53194021 = "Jika Anda tidak merawatnya dengan cepat, itu akan berubah menjadi ubin yang rusak, yang menimbulkan masalah besar!",
  str_story_banner_53195011 = "Banyak Aurorian Hutan ahli dalam memanfaatkan ubin yang disempurnakan.",
  str_story_banner_53196011 = "Sekarang waktunya bagi Fire Aurorian untuk memamerkan barang-barang mereka dan mengambil skenario yang benar-benar baru.",
  str_story_banner_53197011 = "Tes terakhir... Ini tidak akan mudah.",
  str_story_banner_53197012 = "Tujuan Anda kali ini adalah menghapus ubin sebanyak mungkin dalam batas putaran dan mengalahkan skor tertinggi!",
  str_story_banner_53197013 = "Setiap kali Anda mencapai tujuan peringkat di tahap tantangan, tahap tersebut akan ditingkatkan.",
  str_story_banner_53197021 = "Sebagai peningkatan tahap, kesulitannya juga akan meningkat!",
  str_story_banner_53197022 = "Navigator, saatnya melepaskan kekuatanmu yang sebenarnya!",
  str_story_banner_60121011 = "Saat Anda mendekati tepi hutan belantara, kabut menggantung di udara, mungkin menyembunyikan makhluk yang diasingkan di dalamnya. Meski pengetahuan kita terbatas tentang tempat ini, tidak perlu panik. Sepertinya seseorang telah berkelana ke sini sebelum kita...",
  str_story_banner_60121012 = "Ranking, Hunting Bounty dan Exiled Harborage telah ditambahkan ke Desolation Codex.",
  str_story_banner_60121013 = "Mari kita periksa!",
  str_story_banner_60121031 = "Sesuai dengan namanya, hutan belantara Desolation Codex yang legendaris menyimpan informasi yang terbatas. Namun, saat Anda menjelajahi rahasianya lebih jauh, Anda akan membuka lebih banyak hadiah yang luar biasa.",
  str_story_banner_60121032 = "Saat siklus Desolation Codex saat ini berakhir, Anda akan menerima Forgotten Utterances dan Forgotten Whispers berdasarkan peringkat Anda.",
  str_story_banner_60121033 = "Anda dapat menukar Ujaran yang Terlupakan dan Bisikan yang Terlupakan dengan Solamber, Aurorian, dan Suar Bintang di Exiled Harborage.",
  str_story_banner_60121051 = "Dalam Peringkat Saat Ini, navigator diurutkan berdasarkan kerusakan yang mereka berikan kepada Bos. Navigator peringkat teratas menerima emblem yang lebih baik sebagai hadiah.",
  str_story_banner_60121091 = "Tantang Bos siklus ini Sekarang!",
  str_story_banner_60122011 = "Saat Anda mendekati tepi hutan belantara, kabut menggantung di udara, mungkin menyembunyikan makhluk yang diasingkan di dalamnya. Meski pengetahuan kita terbatas tentang tempat ini, tidak perlu panik. Sepertinya seseorang telah berkelana ke sini sebelum kita...",
  str_story_banner_60122012 = "Tugas kita di Desolation Codex adalah menghadapi Boss yang dikenal sebagai The Forsaken atau semacamnya. Reward yang kita terima, seperti rank, emblem, dan Lumamber, akan ditentukan oleh damage yang kita berikan kepada Boss.",
  str_story_banner_60122051 = "Anda dapat melihat standar kerusakan dan hadiah semua peringkat di sini.",
  str_story_banner_60122052 = "Di akhir setiap siklus, hadiah dan lambang akan diberikan sesuai dengan peringkat Anda. Semakin tinggi peringkat Anda, semakin besar hadiahnya.",
  str_story_banner_60122053 = "Lambang Anda akan ditampilkan di avatar pribadi Anda sebagai simbol pencapaian Anda.",
  str_story_banner_60122054 = "Saat siklus Desolation Codex saat ini berakhir, Anda akan menerima Forgotten Utterances dan Forgotten Whispers berdasarkan peringkat Anda.",
  str_story_banner_60122055 = "Anda dapat menukar Ujaran yang Terlupakan dan Bisikan yang Terlupakan dengan Solamber, Aurorian, dan Suar Bintang di Exiled Harborage.",
  str_story_banner_60122071 = "Dalam Peringkat Saat Ini, Navigator diurutkan berdasarkan kerusakan yang mereka berikan kepada Bos. Navigator peringkat teratas menerima emblem yang lebih baik sebagai hadiah.",
  str_story_banner_60122111 = "Tantang Bos siklus ini Sekarang!",
  str_story_banner_53240021 = "Lihat, Eclipsites telah muncul di kejauhan! Tapi jangan khawatir! Aku mendukungmu!",
  str_story_banner_53240022 = "Aneh. Kenapa mereka tidak tersingkir...",
  str_story_banner_53240023 = "Ah, jadi Eclipsites memblokir jalan dengan pecahan ubin, mencegah kami mendekat untuk menyerang!",
  str_story_banner_53240024 = "Bagian dari tugas saya adalah menghilangkan semua rintangan dan membersihkan jalan untuk Anda.",
  str_story_banner_53240025 = "Keluarkan Keterampilan Aktif untuk menghubungkan lebih banyak ubin. Kemudian saya akan menggunakan Chain Combo untuk menghilangkan rintangan ini.",
  str_story_banner_53240011 = "Sepertinya hari ini akan menjadi hari yang damai, PlayerName.",
  str_story_banner_53240012 = "Oh? Gerhana? Kesempatan sempurna untuk meregangkan otot-otot itu.",
  str_story_banner_53240013 = "Eclipsite ini lemah. Mari kita urus yang di kiri dulu.",
  str_story_banner_53240014 = "PlayerName, itu telah memasuki kondisi Kebijaksanaan Suci dan memperoleh poin Kebijaksanaan. Kamu bisa melihat penanda di atas bar HP-nya.",
  str_story_banner_53240015 = "Saat memberikan kerusakan pada musuh dalam keadaan Kebijaksanaan Suci, saya dapat mengabaikan perisai mereka dan mengubah kerusakan menjadi poin Kebijaksanaan.",
  str_story_banner_53240016 = "Ketika poin Kebijaksanaan melebihi HP musuh saat ini, saya dapat membunuhnya terlepas dari perisainya. Mari kita selesaikan ini dengan cepat!",
  str_story_banner_53340021 = "PlayerName, langkah pertama bagi pria dewasa adalah selalu tetap tenang.",
  str_story_banner_53340022 = "Sedikit menyusahkan saat ini, tapi saya akan selesaikan dalam waktu singkat.",
  str_story_banner_53340023 = "Aku akan mengumpulkan ubin biru dengan kekuatanku untuk memicu Dari Dawn Sampai Senja untuk penyembuhan.",
  str_story_banner_53340024 = "Selanjutnya, Langkah 2: Pelajari cara menghadapi situasi sulit",
  str_story_banner_53340025 = "Active Skill ku, Tarian Mimpi Bangun, dapat mengacak baris dan kolom hanya dengan beberapa ketukan. Sekarang, giliran kamu.",
  str_story_banner_53340011 = "Eclipsite di wilayahku? Itu mengancam investasi saya! Tunggu saja, saya akan menunjukkan pintu keluar untuk mereka sendiri!",
  str_story_banner_53340012 = "Gunakan Jackpot untuk mengirim mereka jauh-jauh!",
  str_story_banner_53340013 = "Kami telah menyimpang sedikit. Sedikit tanah ekstra perlu dilalui untuk kembali ke jalur yang benar.",
  str_story_banner_53340014 = "Besar atau pulang! Dan bagian terbaiknya—Resikonya Semua Milik Anda.",
  str_story_banner_53340015 = "EveSetiap orang siap! Mari kita habisi mereka sekaligus!",
  str_story_banner_80010101 = "Navigator, sepertinya Eve terjebak dalam mimpi!",
  str_story_banner_80010201 = "Apa yang terjadi dengan saya? Kepalaku pusing...",
  str_story_banner_80010301 = "Kemana perginya bayangan itu...?",
  str_story_banner_80010401 = "Apa yang dijatuhkan bayangan itu?",
  str_story_banner_53340031 = "Musuh tersebar, jadi kita perlu menyebarkan Kadal Besi di tengah untuk menarik mereka untuk dimusnahkan.",
  str_story_banner_53340032 = "Ketuk Iron Lizard, dan setiap putaran Anda dapat menggunakan Magnetix atau Whirlpool untuk beradaptasi dengan situasi medan perang!",
  str_story_banner_53440021 = "Eclipsites akan datang. Ini adalah tanggung jawab saya untuk menjaga tempat ini!",
  str_story_banner_53440022 = "Lepaskan Holy Blitz pada musuh dengan tumpukan Lingering Will tertinggi!",
  str_story_banner_53440023 = "Makhluk kegelapan abadi! Rasakan kekuatan dari God of Light!",
  str_story_banner_53430011 = "Ayo pemanasan, PlayerName, mulai dari yang terbesar!",
  str_story_banner_53430012 = "Dengan Red Baron yang baru, kekuatannya dapat diperkuat dalam kondisi tertentu. Pastikan untuk mengingat hal ini untuk pertempuran mendatang.",
  str_story_banner_53430013 = "Musuh yang diserang oleh Active Skills akan memasuki status Thunderous Echo. Setiap kali saya melakukan gerakan, saya memberikan damage kepada musuh yang berada dalam status Thunderous Echo di sekitar.",
  str_story_banner_53430014 = "Sekarang, tolong pandu saya, PlayerName. Aku akan menunjukkan kekuatanku.",
  str_story_banner_50620001 = "Benarkah, PlayerName? Takut pada Eclipsite ini?",
  str_story_banner_50620002 = "Jangan khawatir. Keadilan mungkin terlambat, tapi tanaman anggur dan aku selalu tepat waktu.",
  str_story_banner_50620003 = "Mari kita selesaikan ini; ini hari yang membosankan lagi.",
  str_story_banner_50620011 = "PlayerName, saya sangat senang kamu menemaniku berpatroli di hutan ini.",
  str_story_banner_50620012 = "Sepertinya tidak hanya Eclipsites yang mengintai di sini, tetapi tanahnya sendiri juga tercemar.",
  str_story_banner_50620013 = "Jangan khawatir; dengan bantuanmu, kita akan menyelesaikan ini.",
  str_story_banner_50620014 = "Inilah kekuatan pemurnian. Saatnya untuk mengalahkan para Eclipsite ini.",
  str_story_banner_80020101 = "Pam? Kenapa kamu kembali lagi?",
  str_story_banner_80020102 = "A-Apakah kamu... Wanita Irridon? Saya hampir tidak mengenali kamu dengan pakaian itu.",
  str_story_banner_80020103 = "Aku harus pergi dan mengajukan banding! Tak bisa kubiarkan keluargaku menderita ketidakadilan ini!",
  str_story_banner_80020104 = "Sekarang bukan waktunya!",
  str_story_banner_80020105 = "Bahkan kamu juga menghentikanku?",
  str_story_banner_80020106 = "Sekarang, pergilah segera, kecuali jika kamu bisa mengalahkan aku!",
  str_story_banner_80020201 = "Apa itu... Mirren Gautier?!",
  str_story_banner_80020202 = "Dia adalah akar dari semua masalah kita, yang membawa aib bagi keluarga kita.",
  str_story_banner_80020203 = "Oh, Dewa Cahaya, jika Engkau melihat ini, mengapa membiarkannya berkeliaran bebas? Bukankah Engkau berniat melindungi kami?",
  str_story_banner_80020204 = "Sekarang aku tidak punya pilihan selain mengambil tindakan dengan tanganku sendiri!",
  str_story_banner_80020301 = "Lebih baik lagi... Siapa kamu sebenarnya?",
  str_story_banner_80020302 = "Ketua Hakim, keluarga saya dan saya telah dituduh secara salah, dan kami berharap Anda dapat membantu kami mencari keadilan dan membersihkan nama kami!",
  str_story_banner_80020303 = "Jadi, apakah kamu dinyatakan bersalah?",
  str_story_banner_80020304 = "Setiap keputusan yang diberikan oleh Balai Kehakiman disahkan oleh Dewa Cahaya, tanpa ada ruang untuk kesalahan.",
  str_story_banner_80020305 = "Sebagai pihak yang bersalah, Anda menolak untuk mengakui kesalahan Anda dan menghadapi hukuman serta secara tidak sah menerobos masuk ke Balai Kehakiman, menghancurkan keputusan suci kami...",
  str_story_banner_80020306 = "Kamu benar-benar keji dan pantas dihukum lebih keras!",
  str_story_banner_80020307 = "...",
  str_story_banner_53540021 = "PlayerName, kita masih memiliki jarak yang harus ditempuh, tapi kita hampir sampai.",
  str_story_banner_53540022 = "Jika kita melewatkan kesempatan pengamatan ini, siapa tahu berapa lama kita harus menunggu untuk kesempatan berikutnya.",
  str_story_banner_53540023 = "Tak menyangka kita akan bertemu Eclipsites di sini! Tetap dekat denganku!",
  str_story_banner_53540024 = "Kita akan mendapatkan penyembuhan ekstra jika kita menempatkan diri di area yang dipilih. Saya yakin kamu bisa memanfaatkannya.",
  str_story_banner_53540011 = "Jadi, beginilah rupa dunia luar...",
  str_story_banner_53540012 = "Meskipun tanpa saudariku di sisiku, aku akan menemukan keberanian untuk bertarung!",
  str_story_banner_53540013 = "Saya dapat dengan bebas mengonversi Tile Kuning atau Hijau yang dipilih menjadi Tile Biru.",
  str_story_banner_53540014 = "Mari mulai dengan mengeluarkan Badai Hujan Es Musim Dingin, dan berikan sentuhan beku pada tanah!",
  str_story_banner_53540015 = "Kamu tidak bisa mengendalikan kekuatan salju dan angin secara berurutan. Coba gunakan Evergreen Whiteout di ronde berikutnya!",
  str_story_banner_53540031 = "Mencari sinyal... Musuh terdeteksi. Membuka Realm dan siap mengumpulkan data!",
  str_story_banner_53540032 = "Selama hitungan mundur, Navigator dapat menukar elemen dari tile yang berdekatan untuk merencanakan jalur serangan yang lebih sesuai.",
  str_story_banner_700102 = "Daftar Keinginan tersedia dalam rekrutmen waktu terbatas ini, dan Daftar Keinginan berisi 1 Aurorian tetap dan 4 Aurorian pilihan Anda.",
  str_story_banner_700103 = "Pilih satu Aurorian bintang 6 dari masing-masing empat elemen untuk 4 Aurorian opsional yang tersisa.",
  str_story_banner_700104 = "Daftar Keinginan mulai berlaku setelah 4 Aurorian ditentukan.",
  str_story_banner_700105 = "Ketika Daftar Keinginan efektif, Semua Aurorian Bintang 6 yang direkrut dijamin berasal dari Daftar Keinginan.",
  str_story_banner_501400511 = "Tak bisa percaya ada begitu banyak Eclipsite di Teluk Twin Pavilions! Berhati-hatilah dalam menghadapi mereka agar tidak membahayakan warga di sekitar.",
  str_story_banner_501400512 = "Perhatikan posisi musuh dengan seksama! Sepertinya ada jalur ubin merah yang bisa dimanfaatkan; Gunakan Shining Begonias untuk menyambungkannya!",
  str_story_banner_501400513 = "Rasakan ini!",
  str_story_banner_501400514 = "Dengan jalur yang terhubung, Eclipsite besar di depan telah <color=#FFB400>dimusnahkan</color> oleh Shining Begonias. Sekarang, menuju ke bagian timur laut medan tempur untuk menangani Eclipsite yang tersisa!",
  str_story_banner_501400515 = "Huh? Jam pasir di tanah sepertinya baru saja terbentuk setelah kerikil hancur, memberikan kesempatan besar untuk mengurangi waktu pendinginan Shining Begonias. Mari kita coba ubin hijau kali ini!",
  str_story_banner_501400611 = "Ada cukup banyak Eclipsites! Tapi kita harus cepat. Semuanya, tetap aman!",
  str_story_banner_501400612 = "Jalur di sekitar Eclipsite ini semua berwarna merah. Mari mulai dengan menggunakan Shining Begonias untuk menghubungkan jalur, lalu <color=#FFB400>lancarkan Serangan Normal pada Eclipsite ini dari berbagai arah</color>, memaksimalkan efek In Times of Need!",
  str_story_banner_501400613 = "Bagus! Mari kita manfaatkan momentum ini dan hapuskan semua Eclipsite!",
  str_story_banner_81001011 = "Ingat, PlayerName? Sebuah kubus aneh muncul di Obelisk of Return!",
  str_story_banner_81001012 = "Tampaknya kubus itu dapat mengaktifkan perangkat Pelatihan Luminatics yang dirancang oleh Caelestite...",
  str_story_banner_81002011 = "Peringatan: Pelatihan telah resmi dimulai. Anda akan terus-menerus menantang berbagai tahapan dalam setiap sesi pelatihan.",
  str_story_banner_81003011 = "Jika putaranmu habis atau kamu kalah, sesi latihan saat ini akan berakhir dan kamu tidak dapat melanjutkan tantanganmu.",
  str_story_banner_81003012 = "Setelah berhasil menyelesaikan semua tahapan, putaran pelatihan saat ini akan berakhir. Semoga sukses, Ayah.",
  str_story_banner_81004011 = "Modul pelatihan diaktifkan...",
  str_story_banner_81004012 = "Selama program pelatihan, kamu hanya perlu mengetuk dan menghapus ubin untuk melawan Eclipsites.",
  str_story_banner_81004013 = "Ketuk ubin untuk memilih ubin dengan elemen yang sama yang terhubung dengannya. Setelah melakukannya, Anda akan melihat pratinjau Chain Combo Aurorian.",
  str_story_banner_81004014 = "Coba saja sendiri.",
  str_story_banner_81005011 = "Mengetuk ubin yang dipilih lagi akan menghapusnya, dan Aurorian dengan elemen yang sama dengan ubin tersebut akan melepaskan Kombo Rantai mereka.",
  str_story_banner_81006011 = "Lanjutkan pertempuran dan kalahkan semua musuh untuk menyelesaikan latihan.",
  str_story_banner_53740021 = "Apakah aku benar-benar bisa menagih utang di sini?",
  str_story_banner_53740022 = "Ck, alih-alih menemukan orang malas, aku malah menemukan beberapa Eclipsite.",
  str_story_banner_53740023 = "Sebaiknya aku cepat-cepat menghabiskan semuanya. Aku mulai merindukan Rebecca sekarang.",
  str_story_banner_53740011 = "Eclipsites... Mengapa mereka ada di sini?",
  str_story_banner_53740012 = "Aku akan mencoba mendekati mereka dan membuat mereka \"pergi\" tanpa rasa sakit...",
  str_story_banner_53740013 = "Gunakan Active Skill Tarian Kupu-Kupu untuk mengubah Tile Biru di sekitar monster menjadi Tile Gelap.",
  str_story_banner_53740014 = "Setelah melewati Tile Gelap, elemen dari tile yang disegarkan di sana harus sama seperti sebelumnya.",
  str_story_banner_53740015 = "Berhenti melawan. Ini akan selesai dalam sekejap dan tidak akan sakit... terlalu banyak.",
  str_story_banner_551103 = "Lihat, Navigator. Ada area baru yang muncul. Ayo kita periksa!",
  str_story_banner_53840011 = "Di kedalaman laut yang penuh misteri, banyak kapal tenggelam yang menyembunyikan berbagai keajaiban dari Longzhou di bawah ombak. Beruntung, dengan bantuan keahlian mekanik, kita dapat mencoba untuk menyelamatkan sisa-sisa kapal, membawa harta karun terpendam ini kembali ke sinar matahari.",
  str_story_banner_53840021 = "Harap diingat bahwa ketika area penyelamatan penuh, penyelamatan akan berakhir dengan kegagalan!",
  str_story_banner_53840031 = "Raih kemenangan dengan berhasil menggali semua Relic di lapangan!",
  str_story_banner_53840032 = "Navigator, kini ada di tangan Anda!",
  str_story_banner_53840041 = "Bersiaplah untuk tantangan paling akbar!",
  str_story_banner_53840042 = "Di sini, relik melimpah, dan kamu harus berusaha untuk menyelamatkan sebanyak mungkin relik dalam batasan waktu yang terbatas!",
  str_story_banner_53840043 = "Pada kesimpulannya, hadiah akan dibagikan berdasarkan skor yang kamu peroleh.",
  str_story_banner_53840044 = "Navigator, saatnya menunjukkan kemampuan sebenarnya Anda!",
  str_story_banner_53840111 = "Mengapa tiba-tiba ada begitu banyak Eclipsite di sini? Yang di sebelah kiri terlihat sangat tangguh. Kita perlu menyiapkan Formasi Petir Persegi dan melawannya dengan hati-hati.",
  str_story_banner_53840112 = "Gunakan Parasol Pull untuk mengeliminasi semua musuh lain yang tersebar di mana-mana.",
  str_story_banner_53840113 = "Sangat menguntungkan bagi kita untuk melawan musuh di Square Thunder Array. Gunakan dengan baik untuk memenangkan semua pertempuran Anda!",
  str_story_banner_53940311 = "Wow, saya telah dikelilingi oleh Eclipsites. Hanya karena saya kecil bukan berarti saya mudah untuk dijahili.",
  str_story_banner_53940312 = "Saya dengar beberapa Eclipsite mencuri barang antik... Apakah mereka benar-benar tahu apa yang mereka curi...?",
  str_story_banner_53940313 = "Gunakan Full Exposure dan mendekatlah untuk memeriksa mereka dengan cermat.",
  str_story_banner_53940211 = "Oh, itu kamu, Pak Istvan. Pakaianmu...",
  str_story_banner_53940212 = "Lupakan itu untuk sekarang, gadis kecil. Mari kita selesaikan masalah yang ada di depan mata terlebih dahulu.",
  str_story_banner_53940213 = "Permainan catur telah dimulai.",
  str_story_banner_53940214 = "Gadis kecil, tunjukkan kemampuanmu mengendalikan Pedang Ajaib.",
  str_story_banner_53940215 = "Terima kasih telah membantuku, Shadowlord.",
  str_story_banner_53940216 = "Permainan sudah ditentukan. Sudah saatnya mengakhiri sandiwara ini.",
  str_story_banner_53940217 = "Bayanganku akan mengisi celah-celah dan membuatnya menjadi lengkap.",
  str_story_banner_53940111 = "Pilih Strategi Investasi selama pertempuran untuk meningkatkan keterampilan Sheol di semua aspek.",
  str_story_banner_53940112 = "Modal yang diperoleh dalam pertempuran akan ditampilkan di area yang ditentukan. Ketuk ini untuk pergi ke Strategi Investasi.",
  str_story_banner_53940113 = "Enam kemampuan di sini dibagi menjadi tiga grup dan akan dibuka seiring Sheol mengumpulkan lebih banyak Capital. Setiap kali grup dibuka, pilih salah satu dari dua kemampuan dan ketuk Invest untuk mendapatkan kemampuan ini. Pilihan tidak bisa diubah dalam pertempuran ini.",
  str_story_banner_53940114 = "Setelah menyelesaikan putaran pertama investasi, Sheol dapat melakukan putaran kedua investasi untuk mendapatkan kemampuan bertarung yang tidak dia miliki di putaran pertama investasi.",
  str_story_banner_53940115 = "Saat ini Anda memiliki 5 Capital. Cobalah untuk berinvestasi di Shadow Snake Entanglement dan Rich and Powerful sekarang untuk melihat apa yang terjadi.",
  str_story_banner_53940116 = "Active Skill dan Chain Combo telah ditingkatkan! Investasi juga dapat dilakukan dalam pertempuran berikutnya untuk mendapatkan kemampuan yang terkunci.",
  str_story_banner_8024001 = "Sepertinya musuh berada di luar jangkauan.",
  str_story_banner_8024002 = "Yah, jika itu masalahnya, biarkan saya mencoba pendekatan yang berbeda dalam bertempur.",
  str_story_banner_8024003 = "Selanjutnya, biar kucoba.",
  str_story_banner_8024004 = "Musuh baru telah muncul. Biarkan saya yang mengurus mereka.",
  str_story_banner_8024005 = "Saya bisa merasakan kekuatan dari Formation Node sekarang. Mari kita coba untuk mengeliminasi semua musuh.",
  str_story_banner_5414011 = "Hei PlayerName, sejak bangun, saya telah menemukan banyak hal keren di dunia ini. Apakah kamu mau bergabung denganku untuk memeriksanya hari ini?",
  str_story_banner_5414012 = "Tapi sebagai Maiden Naga, aku harus menangani masalah terdekat terlebih dahulu.",
  str_story_banner_5414013 = "Tidak banyak kesempatan bagi saya untuk menunjukkan kemampuan saya, jadi kamu sebaiknya menghargainya.",
  str_story_banner_5414014 = "Baiklah, lihat aku menangani kekacauan ini!",
  str_story_banner_5414031 = "Saat Festival Musim Semi mendekat, roh-roh jahat kembali membuat onar.",
  str_story_banner_5414032 = "Musuh-musuh berkumpul di sudut, dan metode konvensional tampaknya tidak bisa mengeliminasi mereka semua sekaligus. Ini adalah waktu yang tepat untuk menggunakan skill aktifku: Grenade Kejutan! Ayo, Ah Ding, mari kita tandai posisi musuh dan hapus mereka dengan damage splash!",
  str_story_banner_5414033 = "Oh, saya lupa memberi tahu kamu, Granat Kejutan saya memiliki beberapa varian. Kamu bisa memilih untuk menggunakan salah satu dari beberapa skill varian, masing-masing dengan periode cooldown yang berbeda setelah casting.",
  str_story_banner_5414034 = "Surprise Grenade Variant I meningkatkan Normal Attacks, sementara Surprise Grenade Variant II memberikan efek knockback ke Chain Combos setelah dilemparkan. Pilihlah skill varian yang berbeda berdasarkan situasi untuk memaksimalkan output damage Anda!",
  str_story_banner_54193101 = "Mereka bilang aku sudah gila... Apakah kamu juga gila? Sama seperti aku?",
  str_story_banner_54193102 = "Gila? Hehe… Hahaha! Panggil aku orang gila jika kamu mau.",
  str_story_banner_54193103 = "Claymore, kamu... Apakah kamu mencoba menyembunyikan jati dirimu di balik nama itu? Achilles, beritahu aku, apa yang sedang terjadi?!",
  str_story_banner_54193104 = "Aku harus menurunkanmu...",
  str_story_banner_54193105 = "Itulah yang terjadi di sini!",
  str_story_banner_54193106 = "Adras",
  str_story_banner_54193107 = "Achilles",
  str_story_banner_16022511 = "Hmph! Kalian berpikir bisa menjebakku hanya dengan beraksi bersama?",
  str_story_banner_16022512 = "Jangan khawatir. Bagi pemburu hebat seperti saya, mangsa penuh dengan titik lemah!",
  str_story_banner_16022513 = "Selama berburu, mangsa sering menunjukkan banyak titik lemah. Aturan pertama dalam berburu adalah menemukan dan memanfaatkan titik-titik lemah ini!",
  str_story_banner_16022514 = "Setelah aku menemukan titik lemah mereka, mangsa ini tidak akan berpeluang melawan tombakku!",
  str_story_banner_900107011 = "Komentar: Kenangan dan emosi yang ditinggalkan oleh pemimpi asli dibungkus lapis demi lapis dalam energi mimpi, membentuk Bola Mimpi.",
  str_story_banner_900107012 = "Sebagai Enlightenermu, saya harus mengingatkanmu bahwa selama penjelajahan, kamu akan memiliki kesempatan untuk mendapatkan Dream Orbs yang tersebar di seluruh mimpi.",
  str_story_banner_900107013 = "Dengan menempatkan Dream Orbs ke dalam Enlightenment Spiral, kamu bisa menganalisis memori pertempuran dalam Dream Orbs, membuka skill terkait untuk membantu Aurorian dalam pertempuran.",
  str_story_banner_900108011 = "Tips: Enlightener akan beralih ke mode Enlightenment Cube, memungkinkannya untuk bertarung bersama Aurorian.",
