  str_story_banner_900108013 = "Setelah Aurorian selesai menghubungkan ubin dan semua Chain Combo mereka dilepaskan, jika Enlightener telah mengumpulkan lebih banyak energi daripada yang dibutuhkan oleh Dream Orbs, Anda kemudian dapat melepaskan skill dari Dream Orbs pada Enlightenment Spiral.",
  str_story_banner_900108014 = "Sekarang Anda dapat mencoba menghubungkan ubin sekali.",
  str_story_banner_900108021 = "Kabar baik: Kamu telah mendapatkan energi. Kamu dapat melihat status pengisian dan detail perakitan dari Dream Orbs di sini.",
  str_story_banner_900108031 = "Komentar: Ada banyak jenis Dream Orbs, di antaranya Charging Orbs dapat membantu Anda mendapatkan energi tambahan dan mempercepat proses pengisian.",
  str_story_banner_900108032 = "Sementara itu, Enhancement Orbs dapat memperkuat Skill Orbs pada Enlightenment Spiral.",
  str_story_banner_900108033 = "Kombinasi yang bijaksana dapat memaksimalkan potensi dari Dream Orbs. Sebagai Enlightenermu, saya percaya kamu pasti akan menemukan kebahagiaan dalam hal ini.",
  str_story_banner_5416011 = "Eclipsites muncul di depan? Sepertinya ini tugas untuk Pemburu Elang.",
  str_story_banner_5416012 = "Tahan posisimu dan gunakan Death Recon untuk mengintai rute infiltrasi.",
  str_story_banner_5416013 = "Melaporkan! Pemburu Elang Nol telah menyusup ke wilayah musuh; saatnya telah tiba untuk memulai serangan kita! Meminta semua drone untuk menyerang musuh!",
  str_story_banner_5416014 = "Coba gunakan Death Recon lagi! Ini akan membuat saya dalam status Lelah dan mencegah saya menggunakan serangan normal atau kombinasi rantai... Tapi Pemburu Elang akan mengunci musuh dan memusnahkan mereka di tempat saya!",
  str_story_banner_5416021 = "Kabar baik, Caelestite Terakhir! Hari ini, kamu memiliki keistimewaan untuk berjuang bersama Zeta, penyelamat seluruh Astra!",
  str_story_banner_5416022 = "Kamu sudah bertemu dengan anggota lain dari grupku, kan? Aku berbicara tentang robot yang sangat menggemaskan ini—Conan yang tercerahkan!",
  str_story_banner_5416023 = "Conan yang tercerahkan tidak menuruti siapa pun selain saya! Keren, kan?",
  str_story_banner_5416024 = "Kamu akan baik-baik saja untuk mengingat ini, The Last Caelestite: begitu Papan Warna ditutupi oleh keempat warna, kamu bisa memanggil Conan yang Pencerahan baru! Aku tidak membagikan keterampilan rahasia ini dengan sembarang orang, jadi simpanlah sebagai rahasia ya?",
  str_story_banner_5466011 = "Saya akan mencetak rekor baru untuk Tetrablox! Tapi ada Eclipsites... Tidak ada jalan lain. Saya harus membasmi kamu untuk mendapatkan lebih banyak poin!",
  str_story_banner_5466012 = "Pertama, dapatkan Antrian Selanjutnya!",
  str_story_banner_5466013 = "Blok yang kamu lihat di tengah layar adalah jangkauan konversi Tile dari Active Skill pada saat ini.",
  str_story_banner_5466014 = "Ketuk tombol di sebelah kanan untuk menggunakan Energi untuk mengacak bentuk.",
  str_story_banner_5466015 = "Bentuk ini adalah yang kamu butuhkan!",
  str_story_banner_5466016 = "Jangan sia-siakan Energi yang tersisa! Ketuk tombol di sebelah kiri untuk mengunci bentuk terlebih dahulu, lalu ketuk yang di sebelah kanan untuk meningkatkannya!",
  str_story_banner_5466017 = "Telah ditingkatkan! Saat Anda menggunakan Skill Aktif berikutnya, Anda akan menghasilkan jumlah Dark Tile yang sama dengan jumlah peningkatan dalam jangkauan skill.",
  str_story_banner_5466018 = "Sekarang saatnya! Gunakan Active Skill untuk melenyapkan Eclipsites!",
  str_story_banner_5486011 = "PlayerName, kamu harus lebih sering keluar dan berjemur di bawah sinar matahari.",
  str_story_banner_5486012 = "Ketika kamu sudah dewasa, aku akan membimbingmu lebih dekat dengan Kebenaran.",
  str_story_banner_5486013 = "Aku akan membersihkan rintangan di jalurmu.",
  str_story_banner_5486014 = "Teruslah berjalan, Truth berada di depanmu.",
