  str_story_banner_5486022 = "Biarkan kekuatan yang menakutkan ini menghancurkan akal sehatmu!",
  str_story_banner_5486031 = "Apakah bahkan Eclipsite yang berdosa sekalipun akan memohon belas kasihan Tuhan?",
  str_story_banner_5486032 = "Dengan Darah Suci yang diberikan oleh Tuhan, saya akan membimbing penebusan dosamu.",
  str_story_banner_5496011 = "Eclipsite telah muncul! Gunakan Active Skill untuk menyerang mereka!",
